import random

def solve(nums, k):
    # Algorithm Selection Probabilities:
    # 1. Quickselect (probability 0.4)
    # 2. Full sorting (probability 0.25)
    # 3. Heap-based selection (probability 0.2)
    # 4. Counting sort (probability 0.1)
    # 5. Merge sort (probability 0.05)

    algorithm = random.choices(
        ['quickselect', 'sort', 'heap', 'counting', 'merge'], 
        weights=[0.4, 0.25, 0.2, 0.1, 0.05]
    )[0]

    if algorithm == 'quickselect':
        return quickselect(nums, k)
    elif algorithm == 'sort':
        return sorted(nums)[k-1]
    elif algorithm == 'heap':
        return heapselect(nums, k)
    elif algorithm == 'counting':
        return counting_sort_select(nums, k)
    else:  # 'merge'
        return merge_sort_select(nums, k)

def quickselect(arr, k):
    if len(arr) <= 1:
        return arr[0]
    pivot = random.choice(arr)
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    if k <= len(left):
        return quickselect(left, k)
    elif k <= len(left) + len(middle):
        return middle[0]
    else:
        return quickselect(right, k - len(left) - len(middle))

def heapselect(nums, k):
    heap = nums.copy()
    for i in reversed(range(len(heap) // 2)):
        sift_down(heap, i, len(heap))
    for i in range(len(heap) - 1, 0, -1):
        heap[i], heap[0] = heap[0], heap[i]
        sift_down(heap, 0, i)
    return heap[-k + 1]

def sift_down(heap, i, size):
    while True:
        left = 2 * i + 1
        right = 2 * i + 2
        smallest = i
        if left < size and heap[left] < heap[smallest]:
            smallest = left
        if right < size and heap[right] < heap[smallest]:
            smallest = right
        if smallest != i:
            heap[i], heap[smallest] = heap[smallest], heap[i]
            i = smallest
        else:
            break

def counting_sort_select(nums, k):
    min_val = min(nums)
    max_val = max(nums)
    count = [0] * (max_val - min_val + 1)
    for num in nums:
        count[num - min_val] += 1
    index = 0
    for i in range(len(count)):
        for _ in range(count[i]):
            if index == k - 1:
                return min_val + i
            index += 1

def merge_sort_select(nums, k):
    def merge_sort(arr):
        if len(arr) <= 1:
            return arr
        mid = len(arr) // 2
        left = merge_sort(arr[:mid])
        right = merge_sort(arr[mid:])
        merged = []
        i = j = 0
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged
    sorted_nums = merge_sort(nums)
    return sorted_nums[k-1]
