import random

def solve(nums, k):
    # Algorithms and their probabilities:
    # 1. Sorting (prob: 0.3)
    # 2. Quickselect (prob: 0.25)
    # 3. Using a heap (prob: 0.2)
    # 4. Counting with a frequency map (prob: 0.15)
    # 5. Brute force with list comprehensions (prob: 0.1)

    algo = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.25, 0.2, 0.15, 0.1])[0]

    if algo == 1:
        # Sorting
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]
    elif algo == 2:
        # Quickselect
        def quickselect(arr, k):
            left, right = 0, len(arr) - 1
            while left <= right:
                pivot = random.randint(left, right)
                arr[left], arr[pivot] = arr[pivot], arr[left]
                pivot = left
                i = left + 1
                for j in range(left + 1, len(arr)):
                    if arr[j] < arr[pivot]:
                        arr[i], arr[j] = arr[j], arr[i]
                        i += 1
                arr[pivot], arr[i-1] = arr[i-1], arr[pivot]
                if i - 1 == k - 1:
                    return arr[k-1]
                elif i - 1 < k - 1:
                    left = i
                else:
                    right = i - 2
            return arr[k-1]
        return quickselect(nums[:], k)
    elif algo == 3:
        # Using a heap
        import heapq
        return heapq.nsmallest(k, nums)[k-1]
    elif algo == 4:
        # Counting with a frequency map
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1
        sorted_keys = sorted(freq.keys())
        count = 0
        for key in sorted_keys:
            count += freq[key]
            if count >= k:
                return key
    elif algo == 5:
        # Brute force with list comprehensions
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]
