import random

def solve(nums, k):
    # Algorithms and their probabilities
    algorithms = [
        ('quickselect', 0.4),
        ('heap', 0.3),
        ('sort', 0.2),
        ('merge_sort', 0.05),
        ('insertion_sort', 0.05)
    ]

    # Choose an algorithm randomly according to the probabilities
    selected = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]

    if selected == 'quickselect':
        return quickselect(nums, k)
    elif selected == 'heap':
        return heap_kth_smallest(nums, k)
    elif selected == 'sort':
        return sorted(nums)[k-1]
    elif selected == 'merge_sort':
        return merge_sort(nums)[k-1]
    elif selected == 'insertion_sort':
        return insertion_sort(nums)[k-1]

def quickselect(nums, k):
    if len(nums) == 1:
        return nums[0]
    pivot = random.choice(nums)
    left = [x for x in nums if x < pivot]
    mid = [x for x in nums if x == pivot]
    right = [x for x in nums if x > pivot]
    if k <= len(left):
        return quickselect(left, k)
    elif k <= len(left) + len(mid):
        return mid[0]
    else:
        return quickselect(right, k - len(left) - len(mid))

def heap_kth_smallest(nums, k):
    import heapq
    return heapq.nsmallest(k, nums)[k-1]

def merge_sort(nums):
    if len(nums) <= 1:
        return nums
    mid = len(nums) // 2
    left = merge_sort(nums[:mid])
    right = merge_sort(nums[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def insertion_sort(nums):
    for i in range(1, len(nums)):
        key = nums[i]
        j = i - 1
        while j >= 0 and key < nums[j]:
            nums[j + 1] = nums[j]
            j -= 1
        nums[j + 1] = key
    return nums
