import random

def solve(nums, k):
    # Algorithm selection probabilities:
    # 1. Sorting (O(n log n)) - 0.3
    # 2. Quickselect (O(n) average, O(n^2) worst) - 0.4
    # 3. Using a heap (O(n log k)) - 0.15
    # 4. Using a frequency dictionary and counting (O(n)) - 0.1
    # 5. Using a list and partitioning (custom quickselect) - 0.05

    algo = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.4, 0.15, 0.1, 0.05])[0]

    if algo == 1:
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]
    elif algo == 2:
        def quickselect(arr, k):
            pivot = random.choice(arr)
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            equals = [x for x in arr if x == pivot]
            if k <= len(lows):
                return quickselect(lows, k)
            elif k <= len(lows) + len(equals):
                return pivot
            else:
                return quickselect(highs, k - len(lows) - len(equals))
        return quickselect(nums, k)
    elif algo == 3:
        import heapq
        return heapq.nsmallest(k, nums)[-1]
    elif algo == 4:
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1
        for key in sorted(freq.keys()):
            if k <= freq[key]:
                return key
            k -= freq[key]
    elif algo == 5:
        def partition(arr, left, right, pivot_idx):
            pivot = arr[pivot_idx]
            arr[right], arr[pivot_idx] = arr[pivot_idx], arr[right]
            store_idx = left
            for i in range(left, right):
                if arr[i] < pivot:
                    arr[i], arr[store_idx] = arr[store_idx], arr[i]
                    store_idx += 1
            arr[right], arr[store_idx] = arr[store_idx], arr[right]
            return store_idx

        def quickselect_custom(arr, left, right, k):
            if left == right:
                return arr[left]
            pivot_idx = random.randint(left, right)
            pivot_idx = partition(arr, left, right, pivot_idx)
            if k == pivot_idx:
                return arr[k]
            elif k < pivot_idx:
                return quickselect_custom(arr, left, pivot_idx - 1, k)
            else:
                return quickselect_custom(arr, pivot_idx + 1, right, k)

        return quickselect_custom(nums, 0, len(nums) - 1, k - 1)
