import random

def solve(nums, k):
    # Algorithm selection probabilities:
    # 1. Sorting (O(n log n)) - 0.3
    # 2. Quickselect (O(n) average, O(n^2) worst) - 0.4
    # 3. Using a heap (O(n log k)) - 0.1
    # 4. Using a partial sort (O(n log k)) - 0.1
    # 5. Using a frequency map and counting (O(n + m)) - 0.1
    # where m is the range of values (up to 20000)
    alg = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.4, 0.1, 0.1, 0.1])[0]

    if alg == 1:
        # Sorting
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]
    elif alg == 2:
        # Quickselect
        def quickselect(arr, k):
            pivot = random.choice(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]
            if k <= len(left):
                return quickselect(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return quickselect(right, k - len(left) - len(mid))
        return quickselect(nums, k)
    elif alg == 3:
        # Using a heap (min-heap of size k)
        import heapq
        heap = nums[:k]
        heapq.heapify(heap)
        for num in nums[k:]:
            if num > heap[0]:
                heapq.heappushpop(heap, num)
        return heap[0]
    elif alg == 4:
        # Using a partial sort (nlargest)
        import heapq
        return heapq.nsmallest(k, nums)[-1]
    elif alg == 5:
        # Using a frequency map
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1
        sorted_keys = sorted(freq.keys())
        for key in sorted_keys:
            if freq[key] >= k:
                return key
            k -= freq[key]
