def solve():
    def add_edge(u, v, w):
        graph[u].append((v, w))

    def is_reachable(s, t):
        visited = set()
        queue = [s]
        visited.add(s)
        while queue:
            node = queue.pop(0)
            if node == t:
                return True
            for neighbor, _ in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    def compute_min_path(s, t):
        if s == t:
            return 0
        if not is_reachable(s, t):
            return -1
        dist = {node: float('inf') for node in graph}
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > d + w:
                    dist[v] = d + w
                    heapq.heappush(heap, (dist[v], v))
        return dist[t]

    graph = defaultdict(list)
    return compute_min_path
