def solve(graph, start, end):
    from collections import deque

    def bfs(node):
        visited = set()
        queue = deque([(node, 0)])
        visited.add(node)
        while queue:
            current, cost = queue.popleft()
            if current == end:
                return cost
            for neighbor, weight in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, cost + weight))
        return -1

    return bfs(start)
