from collections import deque

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    # Since n <= 100 and edges <= 600, Bellman-Ford is efficient enough
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in graph[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w

    # Check for negative weight cycles (if any)
    for u in range(n):
        if dist[u] != float('inf'):
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    # If we can still relax, there's a negative cycle
                    if t == v:
                        return -1  # Negative cycle exists and t is reachable

    return dist[t] if dist[t] != float('inf') else -1
