    dist[s] = 0
    visited = [False] * n
    queue = deque()
    queue.append(s)

    while queue:
        u = queue.popleft()
        visited[u] = True
        for v, w in graph[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                if not visited[v]:
                    queue.append(v)

    return dist[t] if dist[t] != float('inf') else -1
