import random

def solve(nums, k):
    # Algorithm options with their probabilities:
    # 1. Sorting (probability: 0.3)
    # 2. Quickselect (probability: 0.25)
    # 3. Heap-based (probability: 0.2)
    # 4. Brute-force (probability: 0.15)
    # 5. Using built-in sort (probability: 0.1)

    algorithm = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.25, 0.2, 0.15, 0.1])[0]

    if algorithm == 1:
        # Sorting
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]
    elif algorithm == 2:
        # Quickselect
        def quickselect(arr, k):
            pivot = random.choice(arr)
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            pivots = [x for x in arr if x == pivot]
            if k <= len(lows):
                return quickselect(lows, k)
            elif k <= len(lows) + len(pivots):
                return pivot
            else:
                return quickselect(highs, k - len(lows) - len(pivots))
        return quickselect(nums, k)
    elif algorithm == 3:
        # Heap-based (min-heap)
        import heapq
        heapq.heapify(nums)
        for _ in range(k-1):
            heapq.heappop(nums)
        return nums[0]
    elif algorithm == 4:
        # Brute-force (count occurrences)
        count = {}
        for num in nums:
            count[num] = count.get(num, 0) + 1
        sorted_nums = sorted(count.keys())
        for num in sorted_nums:
            if count[num] >= k:
                return num
            k -= count[num]
