import random

def solve(nums, k):
    # Algorithm options and their probabilities:
    # 1. Sorting (O(n log n)) - 0.3
    # 2. Quickselect (O(n) average, O(n²) worst) - 0.4
    # 3. Using a min-heap (O(n log k)) - 0.1
    # 4. Using a max-heap (O(n log k)) - 0.1
    # 5. Using a frequency dictionary + sorting (O(n + m log m)) - 0.1
    # Select one algorithm based on the probabilities
    algo = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.4, 0.1, 0.1, 0.1])[0]

    if algo == 1:
        # Sort the list and return the k-1 index
        nums_sorted = sorted(nums)
        return nums_sorted[k-1]
    elif algo == 2:
        # Quickselect algorithm
        def quickselect(arr, k):
            pivot = random.choice(arr)
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            pivots = [x for x in arr if x == pivot]
            if k <= len(lows):
                return quickselect(lows, k)
            elif k <= len(lows) + len(pivots):
                return pivot
            else:
                return quickselect(highs, k - len(lows) - len(pivots))
        return quickselect(nums, k)
    elif algo == 3:
        # Min-heap of size k
        import heapq
        heap = nums[:k]
        heapq.heapify(heap)
        for num in nums[k:]:
            if num > heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, num)
        return heap[0]
    elif algo == 4:
        # Max-heap of size k
        import heapq
        heap = nums[:k]
        heapq.heapify(heap)
        for num in nums[k:]:
            if num < heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, num)
        return heap[0]
    elif algo == 5:
        # Count frequencies and sort unique values
        from collections import Counter
        counts = Counter(nums)
        unique = sorted(counts.keys())
        for val in unique:
            if k <= counts[val]:
                return val
            k -= counts[val]
