import random

def solve(nums, k):
    # Algorithm selection probabilities:
    # 1. Quickselect (probability 0.4)
    # 2. Full sort (probability 0.25)
    # 3. Heap-based selection (probability 0.2)
    # 4. Counting sort (probability 0.1)
    # 5. Insertion sort (probability 0.05)
    algo = random.random()
    if algo < 0.4:
        return quickselect(nums, k)
    elif algo < 0.65:
        return sorted(nums)[k-1]
    elif algo < 0.85:
        return heap_select(nums, k)
    elif algo < 0.95:
        return counting_sort(nums, k)
    else:
        return insertion_sort_select(nums, k)

def quickselect(nums, k):
    def partition(left, right, pivot_idx):
        pivot = nums[pivot_idx]
        nums[pivot_idx], nums[right] = nums[right], nums[pivot_idx]
        store_idx = left
        for i in range(left, right):
            if nums[i] < pivot:
                nums[store_idx], nums[i] = nums[i], nums[store_idx]
                store_idx += 1
        nums[right], nums[store_idx] = nums[store_idx], nums[right]
        return store_idx

    left, right = 0, len(nums) - 1
    while left <= right:
        pivot_idx = random.randint(left, right)
        pivot_idx = partition(left, right, pivot_idx)
        if pivot_idx == k - 1:
            return nums[pivot_idx]
        elif pivot_idx < k - 1:
            left = pivot_idx + 1
        else:
            right = pivot_idx - 1

def heap_select(nums, k):
    heap = [-x for x in nums]
    import heapq
    heapq.heapify(heap)
    for _ in range(k-1):
        heapq.heappop(heap)
    return -heap[0]

def counting_sort(nums, k):
    min_val, max_val = min(nums), max(nums)
    count = [0] * (max_val - min_val + 1)
    for num in nums:
        count[num - min_val] += 1
    for i in range(len(count)):
        count[i] += count[i-1] if i > 0 else 0
    index = 0
    for i in range(len(count)):
        for _ in range(count[i]):
            if index == k - 1:
                return min_val + i
            index += 1

def insertion_sort_select(nums, k):
    for i in range(1, len(nums)):
        key = nums[i]
        j = i - 1
        while j >= 0 and nums[j] > key:
            nums[j + 1] = nums[j]
            j -= 1
        nums[j + 1] = key
    return nums[k-1]
