    selected = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if selected == "Quickselect":
        def quickselect(arr, k):
            if len(arr) == 1:
                return arr[0]
            pivot = random.choice(arr)
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            pivots = [x for x in arr if x == pivot]
            if k <= len(lows):
                return quickselect(lows, k)
            elif k <= len(lows) + len(pivots):
                return pivot
            else:
                return quickselect(highs, k - len(lows) - len(pivots))
        return quickselect(nums, k)
    elif selected == "Full sort":
        nums.sort()
        return nums[k-1]
    elif selected == "Heap-based selection":
        import heapq
        return heapq.nsmallest(k, nums)[-1]
    elif selected == "Iterative selection":
        copy = nums.copy()
        for i in range(k-1):
            min_val = min(copy)
            copy.remove(min_val)
        return min_val
    elif selected == "Partition-based selection":
        def partition(arr, low, high):
            pivot = arr[high]
            i = low - 1
            for j in range(low, high):
                if arr[j] <= pivot:
                    i += 1
                    arr[i], arr[j] = arr[j], arr[i]
            arr[i+1], arr[high] = arr[high], arr[i+1]
            return i + 1

        def partition_based(arr, low, high, k):
            if low <= high:
                pi = partition(arr, low, high)
                if pi == k - 1:
                    return arr[pi]
                elif pi < k - 1:
                    return partition_based(arr, pi + 1, high, k)
                else:
                    return partition_based(arr, low, pi - 1, k)
            return -1

        copy = nums.copy()
        return partition_based(copy, 0, len(copy) - 1, k)
