        min_val = min(nums)
        max_val = max(nums)
        count = [0] * (max_val - min_val + 1)
        for num in nums:
            count[num - min_val] += 1
        for i in range(len(count)):
            if count[i] >= k:
                return min_val + i
            k -= count[i]
    else:
        # Randomized selection
        def randomized_select(arr, k):
            if len(arr) == 1:
                return arr[0]
            pivot = random.choice(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
