import random

def solve(nums, k):
    # Algorithm options with their selection probabilities
    # 1. Sorting (O(n log n)) - probability 0.3
    # 2. Quickselect (O(n) average, O(n^2) worst) - probability 0.2
    # 3. Using a heap (O(n log k)) - probability 0.2
    # 4. Counting sort (O(n + range)) - probability 0.15
    # 5. Using a list and k-th element (O(1) for k=1, O(n) for k=n) - probability 0.15

    # Randomly select an algorithm based on the probabilities
    algo = random.choices(
        ['sort', 'quickselect', 'heap', 'counting_sort', 'direct'],
        weights=[0.3, 0.2, 0.2, 0.15, 0.15]
    )[0]

    if algo == 'sort':
        return sorted(nums)[k-1]
    elif algo == 'quickselect':
        def quickselect(arr, k):
            if len(arr) == 1:
                return arr[0]
            pivot = random.choice(arr)
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            pivots = [x for x in arr if x == pivot]
            if k <= len(lows):
                return quickselect(lows, k)
            elif k <= len(lows) + len(pivots):
                return pivot
            else:
                return quickselect(highs, k - len(lows) - len(pivots))
        return quickselect(nums, k)
    elif algo == 'heap':
        import heapq
        return heapq.nsmallest(k, nums)[-1]
    elif algo == 'counting_sort':
        min_val = min(nums)
        max_val = max(nums)
        count = [0] * (max_val - min_val + 1)
        for num in nums:
            count[num - min_val] += 1
        for i in range(len(count)):
            if count[i] > 0:
                for _ in range(count[i]):
                    if k == 1:
                        return min_val + i
                    k -= 1
        return min_val + i
    elif algo == 'direct':
        return nums[k-1] if k == 1 else solve(nums, k-1)
