    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    matrix = []
    index = 2

    for i in range(n):
        row = list(map(int, data[index:index + m]))
        matrix.append(row)
        index += m

    def dfs(row, col, visited):
        if row < 0 or row >= n or col < 0 or col >= m or (row, col) in visited:
            return False
        visited.add((row, col))
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                if dfs(row + dr, col + dc, visited):
                    return True
        return False

    for i in range(n):
        for j in range(m):
            visited = set()
            if dfs(i, j, visited):
                print(i, j)
                return
    print(-1, -1)

if __name__ == "__main__":
