class Solution:
    def removeDuplicates(self, nums: List[int]) -> List[int]:
        if not nums:
            return []
        i = 0
        for j in range(1, len(nums)):
            if nums[j] != nums[i]:
                i += 1
                nums[i] = nums[j]
        return nums[:i+1]
