def solve(nums):
    def _helper(nums, index):
        if index < 0:
            return
        if nums[index] <= 0:
            return
        val = nums[index]
        nums[index] = -1
        _helper(nums, val - 1)

    for i in range(len(nums)):
        _helper(nums, nums[i] - 1)

    for i in range(len(nums)):
        if nums[i] > 0:
            return nums[i]
    return -1
```

