def solve():
    import random
    import string

    def create_data(n):
        data = []
        for _ in range(n):
            data.append(random.choice(string.ascii_letters))
        return data

    def is_safe(data, target):
        count = 0
        for char in data:
            if char == target:
                count += 1
                if count > 1:
                    return False
        return True

    def find_duplicate(data):
        seen = set()
        for char in data:
            if char in seen:
                return char
            seen.add(char)
        return None

    data = create_data(100)
    duplicate = find_duplicate(data)
    if duplicate:
        return duplicate
    else:
        return None
