def solve():
    def dfs(node, visited, graph, path, result):
        if node in path:
            result[0] = node
            return True
        if node in visited:
            return False
        visited.add(node)
        path.append(node)
        for neighbor in graph[node]:
            if dfs(neighbor, visited, graph, path, result):
                return True
        path.pop()
        return False

    def find_cycle_start(graph, nodes):
        visited = set()
        for node in nodes:
            if node not in visited:
                path = []
                result = [None]
                if dfs(node, visited, graph, path, result):
                    return result[0]
        return None

    # Example graph structure (for demonstration only, not used in actual logic)
    # Replace this with actual graph input if needed
    graph = {
        1: [2],
        2: [3],
        3: [4],
        4: [2],
        5: [6],
        6: [5]
    }
    nodes = list(graph.keys())
    return find_cycle_start(graph, nodes)
