```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int start;
    int end;
} Edge;

typedef struct {
    int count;
    Edge* edges;
} Graph;

typedef struct {
    int* parent;
    int* rank;
} DisjointSet;

void initializeDisjointSet(int n, DisjointSet* ds) {
    ds->parent = (int*)malloc(n * sizeof(int));
    ds->rank = (int*)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        ds->parent[i] = i;
        ds->rank[i] = 1;
    }
}

int find(DisjointSet* ds, int x) {
    if (ds->parent[x] != x) {
        ds->parent[x] = find(ds, ds->parent[x]);
    }
    return ds->parent[x];
}

void unionSets(DisjointSet* ds, int x, int y) {
    int rootX = find(ds, x);
    int rootY = find(ds, y);
    if (rootX == rootY) return;
    if (ds->rank[rootX] > ds->rank[rootY]) {
        ds->parent[rootY] = rootX;
    } else if (ds->rank[rootX] < ds->rank[rootY]) {
        ds->parent[rootX] = rootY;
    } else {
        ds->parent[rootY] = rootX;
        ds->rank[rootX]++;
    }
}

void addEdgeToGraph(Graph* graph, int start, int end) {
    graph->edges = (Edge*)realloc(graph->edges, graph->count * sizeof(Edge));
    graph->edges[graph->count++] = (Edge){start, end};
}

void buildGraph(int numVertices, int numEdges, int* edges, Graph* graph) {
    graph->count = 0;
    for (int i = 0; i < numEdges; i++) {
        addEdgeToGraph(graph, edges[2 * i], edges[2 * i + 1]);
    }
}

void initializeGraph(int numVertices, Graph* graph) {
    graph->count = 0;
    graph->edges = NULL;
}

int findConnectedComponents(int numVertices, int numEdges, int* edges) {
    Graph graph;
    initializeGraph(numVertices, &graph);
    buildGraph(numVertices, numEdges, edges, &graph);

    DisjointSet ds;
    initializeDisjointSet(numVertices, &ds);

    for (int i = 0; i < graph.count; i++) {
        int start = graph.edges[i].start;
        int end = graph.edges[i].end;
        unionSets(&ds, start, end);
    }

    int uniqueRoots = 0;
    for (int i = 0; i < numVertices; i++) {
        if (find(&ds, i) == i) {
            uniqueRoots++;
        }
    }

    free(ds.parent);
    free(ds.rank);
    free(graph.edges);

    return uniqueRoots;
}
