using namespace std;

class Solution {
public:
    vector<int> findClosestElements(vector<int>& nums, int k) {
        int left = 0, right = nums.size() - 1;
        while (right - left > k) {
            if (nums[left] + nums[right] <= nums[left + 1] + nums[right - 1]) {
                right--;
            } else {
                left++;
            }
        }
        vector<int> result(nums.begin() + left, nums.begin() + left + k);
        return result;
    }
