class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.adj = {v: [] for v in vertices}

    def add_edge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)

    def bfs(self, start):
        visited = set()
        queue = [start]
        visited.add(start)
        while queue:
            current = queue.pop(0)
            for neighbor in self.adj[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return visited

def process_graph(vertices, edges):
    graph = Graph(vertices)
    for u, v in edges:
        graph.add_edge(u, v)
    return graph
