class Solution:
    def solve(self, n: int, edges: List[List[int]]) -> int:
        # Create adjacency list
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        count = 0

        def dfs(node):
            if visited[node]:
                return
            visited[node] = True
            for neighbor in adj[node]:
                dfs(neighbor)

        for i in range(n):
            if not visited[i]:
                dfs(i)
                count += 1

        return count
