def solve(grid):
    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or visited[i][j]:
            return
        visited[i][j] = True
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if grid[ni][nj] == 1:
                dfs(ni, nj)

    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count
