def solve():
    def count_components():
        n = 400  # Assuming a fixed size for the problem
        edges = [[0, 1], [0, 2], [1, 2], [3, 4], [5, 6]]
        visited = [False] * n
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                stack = [i]
                visited[i] = True
                while stack:
                    node = stack.pop()
                    for neighbor in get_neighbors(node):
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            stack.append(neighbor)
        return count

    def get_neighbors(node):
        neighbors = []
        for u, v in edges:
            if u == node:
                neighbors.append(v)
            elif v == node:
                neighbors.append(u)
        return neighbors

    return count_components()
