#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int x;
    int y;
    int weight;
} Edge;

typedef struct {
    int *parent;
    int size;
} DisjointSet;

void initDisjointSet(DisjointSet *ds, int n) {
    ds->parent = (int *)malloc(n * sizeof(int));
    ds->size = n;
    for (int i = 0; i < n; i++) {
        ds->parent[i] = i;
    }
}

int find(DisjointSet *ds, int x) {
    if (ds->parent[x] != x) {
        ds->parent[x] = find(ds, ds->parent[x]);
    }
    return ds->parent[x];
}

void unionSets(DisjointSet *ds, int x, int y) {
    int rootX = find(ds, x);
    int rootY = find(ds, y);
    if (rootX != rootY) {
        ds->parent[rootY] = rootX;
    }
}

int main() {
    int n;
    scanf("%d", &n);
    Edge *edges = (Edge *)malloc(n * sizeof(Edge));
    for (int i = 0; i < n; i++) {
        scanf("%d %d %d", &edges[i].x, &edges[i].y, &edges[i].weight);
    }

    DisjointSet ds;
    initDisjointSet(&ds, n);

    for (int i = 0; i < n; i++) {
        unionSets(&ds, edges[i].x, edges[i].y);
    }

    int components = 0;
    for (int i = 0; i < n; i++) {
        if (find(&ds, i) == i) {
            components++;
        }
    }

    printf("%d\n", components);

    free(ds.parent);
    free(edges);
    return 0;
}
