from typing import List
from dataclasses import dataclass
import json

@dataclass
class Node:
    value: int
    neighbors: List[int] = None

def solve(edges: List[List[int]]) -> List[List[int]]:
    if not edges:
        return []

    nodes = {}
    for u, v in edges:
        if u not in nodes:
            nodes[u] = Node(u)
        if v not in nodes:
            nodes[v] = Node(v)
        nodes[u].neighbors = nodes[u].neighbors or []
        nodes[u].neighbors.append(v)
        nodes[v].neighbors = nodes[v].neighbors or []
        nodes[v].neighbors.append(u)

    visited = set()
    result = []

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        for neighbor in nodes[node].neighbors:
            dfs(neighbor)
        result.append(node)

    for node in nodes:
        if node not in visited:
            dfs(node)

    return [list(map(lambda x: x, component)) for component in zip(*[iter(result)] * 2)]
