#include <iostream>
#include <vector>
#include <queue>
#include <unordered_set>

using namespace std;

class Solution {
public:
    bool canReachTarget(int n, vector<vector<int>>& graph) {
        vector<bool> visited(n, false);
        queue<int> q;
        q.push(0);
        visited[0] = true;

        while (!q.empty()) {
            int node = q.front();
            q.pop();
            for (int neighbor : graph[node]) {
                if (!visited[neighbor]) {
                    visited[neighbor] = true;
                    q.push(neighbor);
                }
            }
        }

        for (bool visitedNode : visited) {
            if (!visitedNode) return false;
        }
        return true;
    }
};

int main() {
    Solution solution;
    int n = 5;
    vector<vector<int>> graph = {
        {1, 2},
        {0, 2, 3},
        {0, 1, 4},
        {1},
        {2}
    };

    if (solution.canReachTarget(n, graph)) {
        cout << "Target is reachable." << endl;
    } else {
        cout << "Target is not reachable." << endl;
    }

    return 0;
}
