def solve(n, edges, s, t):
    if s == t:
        return 0

    # Initialize distance array with infinity
    import sys
    INF = sys.maxsize
    dist = [INF] * n
    dist[s] = 0

    # Bellman-Ford algorithm to handle possible negative weights (though weights are non-negative here)
    for i in range(n):
        for u, v, w in edges:
            if dist[u] != INF and dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                # If we are on the nth iteration, there's a negative cycle
                if i == n - 1:
                    return -1

    return dist[t] if dist[t] != INF else -1
