def solve(n, edges, a, b):
    from collections import defaultdict

    # Build the adjacency list for the directed graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Function to check if a path from a to b exists with total weight 0
    def dfs(node, path, visited, total):
        if node == b:
            return total == 0
        if node in visited:
            return False
        visited.add(node)
        for neighbor, weight in graph[node]:
            if dfs(neighbor, path + [neighbor], visited, total + weight):
                return True
        visited.remove(node)
        return False

    # Check if there is a path from a to b with total weight 0
    if dfs(a, [a], set(), 0):
        return 0
    return -1
