def solve(n, edges, s, t):
    if s == t:
        return 0

    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Initialize distance array with infinity
    INF = float('inf')
    dist = [INF] * n
    dist[s] = 0

    # Use Bellman-Ford algorithm to detect negative cycles
    # and find shortest paths
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == INF:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative cycles that are reachable from s
    # If any node has distance updated in nth iteration, it's part of a negative cycle
    # But we only care if t is reachable through such a cycle
    # We'll run one more iteration to detect any changes
    updated = False
    for u in range(n):
        if dist[u] == INF:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                updated = True
    if updated:
        # If t is reachable through a negative cycle, then it's not bounded
        # But the problem says the process stops when no changes occur, so we assume no negative cycles
        # But to be safe, we check if dist[t] is still infinity after this
        # If it's not, it's because the cycle affected the path
        # So we return -1 if we can't reach t
        if dist[t] == INF:
            return -1
        else:
            # In case of negative cycles, the shortest path may be undefined
            # But the problem seems to assume no negative cycles (since it stops when no changes)
            # So we just return the computed distance
            return dist[t]

    return dist[t] if dist[t] != INF else -1
