def solve(n, edges, s, t):
    from collections import deque

    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to detect negative cycles and find shortest path
    # We will use a modified Bellman-Ford to handle possible negative weights
    # Since the weights are non-negative (0 <= w <= 100), we can also use Dijkstra's algorithm
    # However, we will use Bellman-Ford to handle cases where there might be negative weights (though in this problem they are not)
    # But since the problem allows for cycles, Bellman-Ford is more appropriate

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                # If there's a negative cycle that is reachable from s and can reach t, then it's unbounded
                # But since all weights are non-negative, this can't happen unless there's a negative cycle
                # So we need to check if t is reachable via such a cycle
                # For this problem, we can assume that if there's a negative cycle, it's not useful for finding a shortest path
                # So we can just return -1 if dist[t] is still infinity
                pass

    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
