    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        for u in range(n):
            if dist[u] == float('inf'):
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w

    # Check for negative weight cycles (if any)
    for u in range(n):
        if dist[u] == float('inf'):
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                # If there's a negative cycle, t might be reachable via it
                # We need to check if t is reachable from s via any path
                # We use BFS to check reachability from s
                visited = [False] * n
                queue = deque([s])
                visited[s] = True
                while queue:
                    node = queue.popleft()
                    if node == t:
                        return -1  # t is reachable via negative cycle
                    for neighbor, _ in adj[node]:
                        if not visited[neighbor]:
                            visited[neighbor] = True
                            queue.append(neighbor)
                # If we reach here, t is not reachable
                return -1

    return dist[t] if dist[t] != float('inf') else -1
