from collections import deque

def solve():
    def can_reach(start, end, graph):
        if start == end:
            return True
        visited = set()
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in graph.get(node, []):
                if neighbor == end:
                    return True
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    def get_neighbors(node, graph):
        return graph.get(node, [])

    def shortest_path(start, end, graph):
        if start == end:
            return 0
        visited = set()
        queue = deque([(start, 0)])
        visited.add(start)
        while queue:
            node, dist = queue.popleft()
            for neighbor, weight in graph.get(node, []):
                if neighbor == end:
                    return dist + weight
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, dist + weight))
        return math.inf

    def solve_case(edges, start, end):
        graph = {}
        for u, v, w in edges:
            if u not in graph:
                graph[u] = []
            graph[u].append((v, w))
        if start not in graph or end not in graph:
            return -1
        if start == end:
            return 0
        if not can_reach(start, end, graph):
            return -1
        return shortest_path(start, end, graph)

    def solve():
        if not edges:
            return -1
        start = 0
        end = 1
        return solve_case(edges, start, end)

