# The solution must not rely on man, the house and baby, so we avoid using any external logic or context.
# We'll use a simple approach that doesn't require any external logic beyond the given constraints.

class Solution:
    def solve(self, board: List[List[str]]) -> None:
        if not board or not board[0]:
            return

        rows, cols = len(board), len(board[0])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Helper function to mark cells as visited
        def mark(i, j):
            board[i][j] = 'X'

        # Traverse the borders first
        for i in range(rows):
            if board[i][0] == 'O':
                mark(i, 0)
            if board[i][cols - 1] == 'O':
                mark(i, cols - 1)

        for j in range(1, cols - 1):
            if board[0][j] == 'O':
                mark(0, j)
            if board[rows - 1][j] == 'O':
                mark(rows - 1, j)

        # Flood fill from the borders
        for i in range(rows):
            for j in range(cols):
                if board[i][j] == 'O':
                    # Check all four directions
                    for dx, dy in directions:
                        ni, nj = i + dx, j + dy
                        if 0 <= ni < rows and 0 <= nj < cols and board[ni][nj] == 'O':
                            board[i][j] = 'X'
                            break

        # Remaining 'O's are enclosed
        for i in range(rows):
            for j in range(cols):
                if board[i][j] == 'O':
                    board[i][j] = 'X'
