        while queue:
            pos, path = queue.popleft()
            if pos == goal:
                return path
            for dr, dc in directions:
                r, c = pos[0] + dr, pos[1] + dc
                if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.' and (r, c) not in visited:
