import json
import sys

def find_path(grid, start, goal):
    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0])

    def is_occupied(r, c):
        return grid[r][c] != ' ' and grid[r][c] != '.'

    def is_goal(r, c):
        return (r, c) == goal

    visited = set()
    queue = [(start[0], start[1], [start])]

    while queue:
        r, c, path = queue.pop(0)
        if (r, c) in visited:
            continue
        visited.add((r, c))

        if is_goal(r, c):
            return path

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if is_valid(nr, nc) and not is_occupied(nr, nc) and (nr, nc) not in visited:
                queue.append((nr, nc, path + [(nr, nc)]))

    return []

def get_grid_from_json(json_str):
    data = json.loads(json_str)
    grid = data.get("grid", [])
    start = data.get("start", None)
    goal = data.get("goal", None)
    if not grid or not start or not goal:
        return None, None, None
    return grid, start, goal

