                        return path + [(nr, nc)]
                    visited.add((nr, nc))
                    queue.append(((nr, nc), path + [(nr, nc)]))
        return []

    path1 = bfs(start, goal)
    path2 = bfs(goal, start)

    # If one of the BFS found a path, return it
    if path1:
        return path1
    if path2:
        return path2[::-1]
    return []
