        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            if dfs(i, visited, -1):
                return True
    return False
