def solve(n, edges):
    from collections import defaultdict

    def has_cycle(node, visited, recursion_stack, adj):
        visited.add(node)
        recursion_stack.add(node)
        for neighbor in adj[node]:
            if neighbor not in visited:
                if has_cycle(neighbor, visited, recursion_stack, adj):
                    return True
            elif neighbor in recursion_stack:
                return True
        recursion_stack.remove(node)
        return False

    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
    recursion_stack = set()
    for node in range(n):
        if node not in visited:
            if has_cycle(node, visited, recursion_stack, adj):
                return True
    return False
