def has_cycle(nodes, edges):
    # Build adjacency list
    graph = {node: [] for node in nodes}
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Track visited nodes
    visited = set()

    # Helper function for DFS
    def dfs(node, parent):
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor != parent:
                if not dfs(neighbor, node):
                    return False
        return True

    # Start DFS from each unvisited node
    for node in nodes:
        if node not in visited:
            if not dfs(node, -1):
                return True
    return False

