def is_bipartite(graph, n):
    color = [-1] * n
    for start in range(n):
        if color[start] == -1:
            queue = [start]
            color[start] = 0
            while queue:
                current = queue.pop(0)
                for neighbor in graph[current]:
                    if color[neighbor] == -1:
                        color[neighbor] = color[current] ^ 1
                        queue.append(neighbor)
                    elif color[neighbor] == color[current]:
                        return False
    return True

