def has_eight_queens_valid(board):
    n = len(board)
    # Check rows
    if any(row.count('Q') > 1 for row in board):
        return False

    # Check columns
    for col in range(n):
        if any(board[row][col] == 'Q' for row in range(n)):
            return False

    # Check diagonals
    for row in range(n):
        for col in range(n):
            if board[row][col] == 'Q':
                # Check top-left to bottom-right diagonal
                i, j = row - 1, col - 1
                while i >= 0 and j >= 0:
