                    i -= 1
                    j -= 1
                # Check bottom-left to top-right diagonal
                i, j = row + 1, col + 1
                while i < n and j < n:
                    if board[i][j] == 'Q':
                        return False
                    i += 1
                    j += 1
                # Check top-right to bottom-left diagonal
                i, j = row - 1, col + 1
                while i >= 0 and j < n:
                    if board[i][j] == 'Q':
                        return False
                    i -= 1
                    j += 1
                # Check bottom-right to top-left diagonal
                i, j = row + 1, col - 1
                while i < n and j >= 0:
                    if board[i][j] == 'Q':
                        return False
                    i += 1
                    j -= 1
    return True
