def solve(nums, target):
    # Algorithm 1: Brute-force (O(n^2)) with probability 0.1
    # Algorithm 2: One-pass Hash Map (O(n)) with probability 0.2
    # Algorithm 3: Two-pointer (sorted list) (O(n log n)) with probability 0.2
    # Algorithm 4: Randomized (O(n) expected) with probability 0.3
    # Algorithm 5: Hash Map with value lookup (O(n)) with probability 0.2

    choice = random.choices([1, 2, 3, 4, 5], weights=[0.1, 0.2, 0.2, 0.3, 0.2])[0]

    if choice == 1:
        # Brute-force
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]
    elif choice == 2:
        # One-pass Hash Map
        num_to_index = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_to_index:
                return [num_to_index[complement], i]
            num_to_index[num] = i
    elif choice == 3:
        # Two-pointer (sorted list)
        nums_sorted = sorted(nums)
        left, right = 0, len(nums_sorted) - 1
        while left < right:
            current_sum = nums_sorted[left] + nums_sorted[right]
            if current_sum == target:
                return [nums.index(nums_sorted[left]), nums.index(nums_sorted[right])]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif choice == 4:
        # Randomized
        while True:
            i = random.randint(0, len(nums) - 1)
            j = random.randint(0, len(nums) - 1)
            if i != j and nums[i] + nums[j] == target:
                return [i, j]
    elif choice == 5:
        # Hash Map with value lookup
        num_to_index = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_to_index:
                return [num_to_index[complement], i]
            num_to_index[num] = i
