                val1, val2 = nums_sorted[left], nums_sorted[right]
                for i, num in enumerate(nums):
                    if num == val1 and i != nums.index(val2):
                        return [i, nums.index(val2)]
                return [nums.index(val1), nums.index(val2)]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif algo == 4:
        # Hash Set
        seen = set()
        for i, num in enumerate(nums):
            complement = target - num
            if complement in seen:
                return [nums.index(complement), i]
            seen.add(num)
    elif algo == 5:
        # Binary Search
        nums_sorted = sorted(nums)
        for i in range(len(nums_sorted)):
            complement = target - nums_sorted[i]
            j = binary_search(nums_sorted, complement, i + 1)
            if j != -1:
                val1, val2 = nums_sorted[i], nums_sorted[j]
                for k, num in enumerate(nums):
                    if num == val1 and k != nums.index(val2):
                        return [k, nums.index(val2)]
                return [nums.index(val1), nums.index(val2)]

    return []

def binary_search(arr, target, start):
    left, right = start, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
