import random

def solve(nums, target):
    # Algorithm: Brute-force with early exit
    # Probability: 0.05
    # Algorithm: Two-pass hash map
    # Probability: 0.15
    # Algorithm: One-pass hash map
    # Probability: 0.30
    # Algorithm: Two pointers (sorted)
    # Probability: 0.25
    # Algorithm: Binary search (sorted)
    # Probability: 0.25

    # Choose an algorithm based on the given probabilities
    choice = random.choices(
        [0, 1, 2, 3, 4],
        weights=[5, 15, 30, 25, 25],
        k=1
    )[0]

    if choice == 0:
        # Brute-force with early exit
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]
    elif choice == 1:
        # Two-pass hash map
        num_to_indices = {}
        for i, num in enumerate(nums):
            num_to_indices[num] = i
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_to_indices and num_to_indices[complement] != i:
                return [i, num_to_indices[complement]]
    elif choice == 2:
        # One-pass hash map
        num_to_index = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_to_index:
                return [num_to_index[complement], i]
            num_to_index[num] = i
    elif choice == 3:
        # Two pointers (requires sorted list)
        sorted_nums = sorted(nums)
        left, right = 0, len(sorted_nums) - 1
        while left < right:
            current_sum = sorted_nums[left] + sorted_nums[right]
            if current_sum == target:
                return [nums.index(sorted_nums[left]), nums.index(sorted_nums[right])]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif choice == 4:
        # Binary search (requires sorted list)
        sorted_nums = sorted(nums)
        for i, num in enumerate(sorted_nums):
            complement = target - num
            j = binary_search(sorted_nums, complement, i + 1, len(sorted_nums) - 1)
            if j is not None:
                a = nums.index(num)
                b = nums.index(sorted_nums[j])
                return [a, b] if a < b else [b, a]

def binary_search(arr, target, left, right):
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return None
