import random

def solve(nums, target):
    # Algorithm 1: Brute Force (Probability: 5%)
    # Algorithm 2: One Pass Hash Map (Probability: 40%)
    # Algorithm 3: Two Pointers (Probability: 25%)
    # Algorithm 4: Hash Set (Probability: 20%)
    # Algorithm 5: Binary Search (Probability: 10%)
    weights = [5, 40, 25, 20, 10]
    choice = random.choices([1, 2, 3, 4, 5], weights=weights)[0]

    if choice == 1:
        # Brute Force
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]
    elif choice == 2:
        # One Pass Hash Map
        num_map = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_map:
                return [num_map[complement], i]
            num_map[num] = i
    elif choice == 3:
        # Two Pointers
        nums_sorted = sorted(nums)
        left, right = 0, len(nums_sorted) - 1
        while left < right:
            current_sum = nums_sorted[left] + nums_sorted[right]
            if current_sum == target:
                # Find original indices
                val1 = nums_sorted[left]
                val2 = nums_sorted[right]
                for i, num in enumerate(nums):
                    if num == val1:
                        idx1 = i
                        break
                for j, num in enumerate(nums):
                    if num == val2 and j != idx1:
                        idx2 = j
                        break
                return [idx1, idx2]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif choice == 4:
        # Hash Set
        seen = set()
        for i, num in enumerate(nums):
            complement = target - num
            if complement in seen:
                for j, n in enumerate(nums):
                    if n == complement and j != i:
                        return [j, i]
            seen.add(num)
    elif choice == 5:
        # Binary Search
        nums_sorted = sorted((val, idx) for idx, val in enumerate(nums))
        for i in range(len(nums_sorted) - 1):
            left, right = i + 1, len(nums_sorted) - 1
            target_val = target - nums_sorted[i][0]
            while left <= right:
                mid = (left + right) // 2
                if nums_sorted[mid][0] == target_val:
                    if nums_sorted[i][1] != nums_sorted[mid][1]:
                        return [nums_sorted[i][1], nums_sorted[mid][1]]
                    right = mid - 1
                elif nums_sorted[mid][0] < target_val:
                    left = mid + 1
                else:
                    right = mid - 1
