    # 3. Two Pointers (O(n log n)) - 20%
    # 4. Binary Search (O(n log n)) - 15%
    # 5. One Pass Hash Map (O(n)) - 5%
    algorithms = [
        ('brute_force', 0.1),
        ('hash_map', 0.5),
        ('two_pointers', 0.2),
        ('binary_search', 0.15),
        ('one_pass_hash_map', 0.05)
    ]

    # Choose an algorithm based on probability
    selected = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if selected == 'brute_force':
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]
    elif selected == 'hash_map':
        seen = {}
        for idx, num in enumerate(nums):
            complement = target - num
            if complement in seen:
                return [seen[complement], idx]
            seen[num] = idx
    elif selected == 'two_pointers':
        nums_sorted = sorted(nums)
        left, right = 0, len(nums_sorted) - 1
        while left < right:
            current_sum = nums_sorted[left] + nums_sorted[right]
            if current_sum == target:
                # Find the original indices
                val1 = nums_sorted[left]
                val2 = nums_sorted[right]
                for i, num in enumerate(nums):
                    if num == val1:
                        idx1 = i
                        break
                for j, num in enumerate(nums):
                    if num == val2:
                        idx2 = j
                        break
                return [idx1, idx2] if idx1 < idx2 else [idx2, idx1]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif selected == 'binary_search':
        nums_sorted = sorted(nums)
        indices = list(range(len(nums)))
        for i in range(len(nums_sorted) - 1):
            complement = target - nums_sorted[i]
            left, right = i + 1, len(nums_sorted) - 1
            while left <= right:
                mid = (left + right) // 2
                if nums_sorted[mid] == complement:
                    # Find the original indices
                    val1 = nums_sorted[i]
                    val2 = nums_sorted[mid]
                    for j, num in enumerate(nums):
                        if num == val1 and j != indices[mid]:
                            idx1 = j
                            break
                    for k, num in enumerate(nums):
                        if num == val2 and k != indices[i]:
                            idx2 = k
                            break
                    return [idx1, idx2] if idx1 < idx2 else [idx2, idx1]
                elif nums_sorted[mid] < complement:
                    left = mid + 1
                else:
                    right = mid - 1
    elif selected == 'one_pass_hash_map':
        seen = {}
        for idx, num in enumerate(nums):
            complement = target - num
            if complement in seen:
                return [seen[complement], idx]
            seen[num] = idx
