    if selected == "brute_force":
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]
    elif selected == "hash_map":
        num_to_index = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_to_index:
                return [num_to_index[complement], i]
            num_to_index[num] = i
    elif selected == "two_pointers":
        nums_sorted = sorted((num, i) for i, num in enumerate(nums))
        left, right = 0, len(nums_sorted) - 1
        while left < right:
            current_sum = nums_sorted[left][0] + nums_sorted[right][0]
            if current_sum == target:
                return [nums_sorted[left][1], nums_sorted[right][1]]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif selected == "hash_set":
        seen = set()
        for i, num in enumerate(nums):
            complement = target - num
            if complement in seen:
                return [nums.index(complement), i]
            seen.add(num)
