        for i, num in enumerate(nums):
            num_to_index[num] = i
        for j, num in enumerate(nums):
            complement = target - num
            if complement in num_to_index and num_to_index[complement] != j:
                return [num_to_index[complement], j]

    elif algorithm == 'one_pass_hash':
        num_to_index = {}
        for j, num in enumerate(nums):
            complement = target - num
            if complement in num_to_index:
                return [num_to_index[complement], j]
            num_to_index[num] = j

    elif algorithm == 'two_pointer':
        nums_sorted = sorted((val, idx) for idx, val in enumerate(nums))
        left, right = 0, len(nums_sorted) - 1
        while left < right:
            current_sum = nums_sorted[left][0] + nums_sorted[right][0]
            if current_sum == target:
                return [nums_sorted[left][1], nums_sorted[right][1]]
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    elif algorithm == 'brute_force':
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]

    elif algorithm == 'binary_search':
        nums_sorted = sorted(nums)
        for i, num in enumerate(nums_sorted):
            complement = target - num
            j = binary_search(nums_sorted, i + 1, len(nums_sorted) - 1, complement)
            if j != -1:
                return [nums.index(num), nums.index(complement)]

    return [-1, -1]

def binary_search(arr, left, right, target):
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1
