import random

def solve(nums):
    # Algorithm: Floyd's Tortoise and Hare (Cycle Detection) - Probability: 0.3
    # Algorithm: Hash Table (Dictionary) - Probability: 0.2
    # Algorithm: Binary Search on Range - Probability: 0.2
    # Algorithm: Negate Values (In-Place) - Probability: 0.2
    # Algorithm: Count Frequencies with List - Probability: 0.1

    # Randomly select an algorithm based on the given probabilities
    algorithms = [
        ("Floyd's Tortoise and Hare", 0.3),
        ("Hash Table", 0.2),
        ("Binary Search on Range", 0.2),
        ("Negate Values", 0.2),
        ("Count Frequencies with List", 0.1)
    ]
    selected = random.choices([alg[0] for alg in algorithms], weights=[alg[1] for alg in algorithms])[0]

    if selected == "Floyd's Tortoise and Hare":
        # Floyd's Tortoise and Hare algorithm to find the duplicate
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        fast = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

    elif selected == "Hash Table":
        seen = {}
        for num in nums:
            if num in seen:
                return num
            seen[num] = True

    elif selected == "Binary Search on Range":
        left, right = 1, len(nums) - 1
        while left < right:
            mid = (left + right) // 2
            count = sum(1 for num in nums if left <= num <= mid)
            if count < mid - left + 1:
                left = mid + 1
            else:
                right = mid
        return left

    elif selected == "Negate Values":
        for num in nums:
            val = abs(num)
            if nums[val - 1] < 0:
                return val
            nums[val - 1] *= -1

    elif selected == "Count Frequencies with List":
        freq = [0] * len(nums)
        for num in nums:
            freq[num - 1] += 1
