import random

def solve(nums):
    # Algorithm 1: Using a hash set (probability 0.25)
    seen = set()
    for num in nums:
        if num in seen:
            return num
        seen.add(num)

    # Algorithm 2: Using Floyd's Tortoise and Hare (cycle detection) (probability 0.25)
    def find_cycle():
        tortoise = nums[nums[0]]
        hare = nums[nums[0]]
        while tortoise != hare:
            tortoise = nums[tortoise]
            hare = nums[nums[hare]]
        hare = nums[0]
        while tortoise != hare:
            tortoise = nums[tortoise]
            hare = nums[hare]
        return tortoise

    # Algorithm 3: Using binary search on counts (probability 0.25)
    def count_in_range(low, high):
        count = 0
        for num in nums:
            if low <= num <= high:
                count += 1
        return count

    def binary_search():
        low, high = 1, len(nums)
        while low < high:
            mid = (low + high) // 2
            cnt = count_in_range(low, mid)
            if cnt > mid - low + 1:
                high = mid
            else:
                low = mid + 1
        return low

    # Algorithm 4: Using the sum of the list (probability 0.15)
    expected_sum = (len(nums) * (len(nums) + 1)) // 2
