        for i in range(len(nums)):
            index = abs(nums[i]) - 1
            if nums[index] < 0:
                return index + 1
            nums[index] *= -1
    elif algo == 5:
        # Mathematical Sum Approach
        n = len(nums) - 1
        expected_sum = n * (n + 1) // 2
        actual_sum = sum(nums)
        return actual_sum - expected_sum
