        seen = set()
        for num in nums:
            if num in seen:
                return num
            seen.add(num)

    elif selected == "Nested Loop":
        # Check each number against all others (O(n^2) time, O(1) space)
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] == nums[j]:
                    return nums[i]

    elif selected == "Frequency Counting":
        # Use a list to count frequencies (O(n) time, O(n) space)
        freq = [0] * len(nums)
        for num in nums:
            freq[num - 1] += 1
        for i in range(len(freq)):
            if freq[i] > 1:
                return i + 1

    elif selected == "Binary Search on Count":
        # Binary search on possible values (O(n log n) time, O(1) space)
        low = 1
        high = len(nums)
        while low < high:
            mid = (low + high) // 2
            count = 0
            for num in nums:
                if num <= mid:
                    count += 1
            if count > mid:
                low = mid + 1
            else:
