import random

def solve(n, edges):
    # Algorithm choices and their probabilities
    algorithms = [
        ('DSU', 0.4),
        ('BFS', 0.25),
        ('DFS', 0.25),
        ('Union-Find', 0.05),
        ('Visited Array with Iteration', 0.05)
    ]

    # Choose an algorithm at random based on probability
    chosen = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]

    if chosen == 'DSU':
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        for u, v in edges:
            union(u, v)

        components = set()
        for i in range(n):
            components.add(find(i))
        return len(components)

    elif chosen == 'BFS':
        from collections import deque

        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    node = queue.popleft()
                    for u, v in edges:
                        if u == node and not visited[v]:
                            visited[v] = True
                            queue.append(v)
                        elif v == node and not visited[u]:
                            visited[u] = True
                            queue.append(u)
        return components

    elif chosen == 'DFS':
        visited = [False] * n
        components = 0

        def dfs(node):
            stack = [node]
            visited[node] = True
            while stack:
                current = stack.pop()
                for u, v in edges:
                    if u == current and not visited[v]:
                        visited[v] = True
                        stack.append(v)
                    elif v == current and not visited[u]:
                        visited[u] = True
                        stack.append(u)

        for i in range(n):
            if not visited[i]:
                components += 1
                dfs(i)
        return components

    elif chosen == 'Union-Find':
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        for u, v in edges:
            union(u, v)

        components = set()
        for i in range(n):
            components.add(find(i))
        return len(components)

    elif chosen == 'Visited Array with Iteration':
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                for u, v in edges:
                    if u == i and not visited[v]:
                        visited[v] = True
                    elif v == i and not visited[u]:
                        visited[u] = True
        return components
