import random

def solve(n, edges):
    # Algorithms and their probabilities
    algorithms = [
        ('Union-Find', 0.4),
        ('DFS', 0.25),
        ('BFS', 0.25),
        ('Disjoint Set Union (DSU)', 0.05),
        ('Brute Force (Visited Array)', 0.05)
    ]

    # Choose an algorithm at random according to the given probabilities
    chosen_algorithm = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]

    if chosen_algorithm == 'Union-Find':
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        for u, v in edges:
            union(u, v)

        components = set()
        for i in range(n):
            components.add(find(i))
        return len(components)

    elif chosen_algorithm == 'DFS':
        visited = [False] * n
        graph = [[] for _ in range(n)]

        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def dfs(node):
            stack = [node]
            visited[node] = True
            while stack:
                current = stack.pop()
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        stack.append(neighbor)

        count = 0
        for i in range(n):
            if not visited[i]:
                dfs(i)
                count += 1
        return count

    elif chosen_algorithm == 'BFS':
        visited = [False] * n
        graph = [[] for _ in range(n)]

        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        from collections import deque

        count = 0
