                        queue.append(neighbor)

        for i in range(n):
            if not visited[i]:
                bfs(i)
                components += 1
        return components

    elif algo == 4:
        # Iterative DFS
        visited = [False] * n
        components = 0

        def iterative_dfs(node):
            stack = [node]
            visited[node] = True
            while stack:
                current = stack.pop()
                for neighbor in range(n):
                    if not visited[neighbor] and any(neighbor == u or neighbor == v for u, v in edges if u == current or v == current):
                        visited[neighbor] = True
                        stack.append(neighbor)

        for i in range(n):
            if not visited[i]:
                iterative_dfs(i)
                components += 1
        return components

    elif algo == 5:
        # Path Tracing with Visited Set
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                current = i
                while True:
                    visited[current] = True
                    next_node = -1
                    for u, v in edges:
                        if u == current and not visited[v]:
                            next_node = v
                            break
                        if v == current and not visited[u]:
                            next_node = u
                            break
                    if next_node == -1:
                        break
                    current = next_node
                components += 1
        return components
