        ('union_find', 0.4),
        ('dfs', 0.2),
        ('bfs', 0.2),
        ('count_isolated', 0.1),
        ('iterative_dfs', 0.1)
    ]

    # Choose an algorithm at random
    chosen = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if chosen == 'union_find':
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

