import random

def solve(n, edges):
    # Algorithms and their probabilities
    algorithms = [
        ('DFS', 0.3),
        ('BFS', 0.3),
        ('Union-Find', 0.2),
        ('Disjoint Set Union (DSU)', 0.15),
        ('Iterative DFS', 0.05)
    ]

    # Choose an algorithm at random based on probabilities
    chosen_alg = random.choices([alg[0] for alg in algorithms], weights=[alg[1] for alg in algorithms])[0]

    if chosen_alg == 'DFS':
        visited = [False] * n
        components = 0

        def dfs(u):
            visited[u] = True
            for v in range(n):
                if not visited[v] and [u, v] in edges or [v, u] in edges:
                    dfs(v)

        for i in range(n):
            if not visited[i]:
                dfs(i)
                components += 1
        return components

    elif chosen_alg == 'BFS':
        visited = [False] * n
        components = 0
        from collections import deque

        def bfs(u):
            visited[u] = True
            queue = deque([u])
            while queue:
                current = queue.popleft()
                for v in range(n):
                    if not visited[v] and ([current, v] in edges or [v, current] in edges):
                        visited[v] = True
                        queue.append(v)

        for i in range(n):
            if not visited[i]:
                bfs(i)
                components += 1
        return components

    elif chosen_alg == 'Union-Find':
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u != root_v:
                parent[root_v] = root_u

        for u, v in edges:
            union(u, v)

        components = len({find(i) for i in range(n)})
        return components

    elif chosen_alg == 'Disjoint Set Union (DSU)':
        parent = list(range(n))

        def find(u):
            if parent[u] != u:
                parent[u] = find(parent[u])
            return parent[u]

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u != root_v:
                parent[root_v] = root_u

        for u, v in edges:
            union(u, v)

        components = len({find(i) for i in range(n)})
        return components

    elif chosen_alg == 'Iterative DFS':
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                stack = [i]
                visited[i] = True
                while stack:
                    u = stack.pop()
                    for v in range(n):
                        if not visited[v] and ([u, v] in edges or [v, u] in edges):
                            visited[v] = True
                            stack.append(v)
                components += 1
        return components
