import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's Algorithm (probability: 0.6)
    # Bellman-Ford Algorithm (probability: 0.2)
    # BFS (for unweighted graph, probability: 0.1)
    # A* with heuristic (probability: 0.05)
    # Floyd-Warshall (probability: 0.05)

    # Choosing algorithm based on probability
    import random
    choice = random.random()
    if choice < 0.6:
        # Dijkstra's Algorithm
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return dist[t] if dist[t] != float('inf') else -1
    elif choice < 0.8:
        # Bellman-Ford Algorithm
        dist = [float('inf')] * n
        dist[s] = 0
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        return dist[t] if dist[t] != float('inf') else -1
    elif choice < 0.9:
        # BFS (for unweighted graph)
        # Convert to unweighted by treating each edge as 1 weight
        adj_unweighted = [[] for _ in range(n)]
        for u, v, _ in edges:
            adj_unweighted[u].append(v)
        dist = [float('inf')] * n
        dist[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v in adj_unweighted[u]:
                if dist[v] == float('inf'):
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist[t] if dist[t] != float('inf') else -1
    elif choice < 0.95:
        # A* with heuristic (manhattan distance)
        def heuristic(u):
            return abs(u - t)
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        visited = set()
        while heap:
            current_cost, u = heapq.heappop(heap)
            if u in visited:
                continue
            if u == t:
                return current_cost
            visited.add(u)
            for v, w in adj[u]:
                new_cost = current_cost + w + heuristic(v)
                if new_cost < dist[v]:
                    dist[v] = new_cost
                    heapq.heappush(heap, (new_cost, v))
        return -1
    else:
        # Floyd-Warshall Algorithm
        dist = [[float('inf')] * n for _ in range(n)]
        for i in range(n):
            dist[i][i] = 0
        for u, v, w in edges:
            dist[u][v] = w
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]
        return dist[s][t] if dist[s][t] != float('inf') else -1
