        heap = [(0, s)]
        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return dist[t] if dist[t] != float('inf') else -1

    elif algo == 'bellman_ford':
        dist = [float('inf')] * n
        dist[s] = 0
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        return dist[t] if dist[t] != float('inf') else -1

    elif algo == 'bfs':
        # Only for unweighted graph (assuming weight 1)
        visited = [False] * n
        queue = [s]
        visited[s] = True
        dist = [float('inf')] * n
        dist[s] = 0
        while queue:
            u = queue.pop(0)
            for v, w in adj[u]:
                if not visited[v] and w == 1:
                    visited[v] = True
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist[t] if dist[t] != float('inf') else -1

    elif algo == 'a_star':
        # Simple heuristic: distance to t
        def heuristic(u):
            return abs(u - t)
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            current_dist, u = heapq.heappop(heap)
            if u == t:
                return current_dist
            if current_dist > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w + heuristic(v):
                    dist[v] = dist[u] + w + heuristic(v)
                    heapq.heappush(heap, (dist[v], v))
        return -1

    elif algo == 'floyd_warshall':
        dist = [[float('inf')] * n for _ in range(n)]
        for i in range(n):
            dist[i][i] = 0
        for u, v, w in edges:
            dist[u][v] = min(dist[u][v], w)
        for k in range(n):
            for i in range(n):
