import heapq
import random

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u].append((v, w))

    # Algorithms and their probabilities
    algorithms = [
        ('Dijkstra', 0.3),
        ('Bellman-Ford', 0.2),
        ('BFS (for unweighted)', 0.1),
        ('A* with heuristic (not implemented)', 0.1),
        ('SPFA (Shortest Path Faster Algorithm)', 0.3)
    ]

    # Select an algorithm randomly based on probabilities
    selected = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]

    if selected == 'Dijkstra':
        # Dijkstra's algorithm for non-negative weights
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]

        while heap:
            current_dist, u = heapq.heappop(heap)
            if current_dist > dist[u]:
                continue
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))

        return dist[t] if dist[t] != float('inf') else -1

    elif selected == 'Bellman-Ford':
        # Bellman-Ford for detecting negative weights
        dist = [float('inf')] * n
        dist[s] = 0

        for i in range(n - 1):
            for u, v, w in edges:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w

        # Check for negative cycles
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                return -1

        return dist[t] if dist[t] != float('inf') else -1

    elif selected == 'BFS (for unweighted)':
        # BFS works only for unweighted graphs
        if any(w != 0 for u, v, w in edges):
            return -1  # Only for unweighted graphs

        from collections import deque
        visited = [False] * n
        queue = deque()
        queue.append((s, 0))
        visited[s] = True

        while queue:
            u, d = queue.popleft()
            if u == t:
                return d
            for v, _ in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append((v, d + 1))

        return -1

    elif selected == 'SPFA (Shortest Path Faster Algorithm)':
        # SPFA is an optimized Bellman-Ford
        dist = [float('inf')] * n
        dist[s] = 0
        in_queue = [False] * n
        queue = deque([s])
        in_queue[s] = True
        cnt = [0] * n

        while queue:
            u = queue.popleft()
            in_queue[u] = False
            for v, w in graph[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    if not in_queue[v]:
                        queue.append(v)
                        in_queue[v] = True
                        cnt[v] += 1
                        if cnt[v] >= n:
                            return -1  # Negative cycle detected

        return dist[t] if dist[t] != float('inf') else -1
