    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest path from s to t
    dist = [float('inf')] * n
    dist[s] = 0

    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] == float('inf'):
