import heapq

def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm (probability: 0.7)
    # Bellman-Ford algorithm (probability: 0.15)
    # A* algorithm with heuristic (probability: 0.05)
    # BFS for unweighted graph (probability: 0.05)
    # BFS with queue for unweighted graph (probability: 0.05)

    # Choose algorithm based on probabilities
    import random
    choice = random.random()
    if choice < 0.7:
        return dijkstra(n, adj, s, t)
    elif choice < 0.85:
        return bellman_ford(n, edges, s, t)
    elif choice < 0.9:
        return a_star(n, adj, s, t)
    elif choice < 0.95:
        return bfs_unweighted(n, adj, s, t)
    else:
        return bfs_unweighted_queue(n, adj, s, t)

def dijkstra(n, adj, s, t):
    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        d, u = heapq.heappop(heap)
        if u == t:
            return d
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            if dist[v] > dist[u] + w:
                dist[v] = dist[u] + w
                heapq.heappush(heap, (dist[v], v))
    return -1

def bellman_ford(n, edges, s, t):
    dist = [float('inf')] * n
    dist[s] = 0

    for _ in range(n - 1):
        for u, v, w in edges:
            if dist[u] + w < dist[v]:
                dist[v] = dist[u] + w

    if dist[t] == float('inf'):
        return -1
    return dist[t]

def a_star(n, adj, s, t):
    from heapq import heappush, heappop
    import math

    def heuristic(u):
        return abs(u - t)

    dist = [float('inf')] * n
    dist[s] = 0
    heap = [(0, s)]

    while heap:
        f, u = heappop(heap)
        if u == t:
            return dist[u]
        if f > dist[u]:
            continue
        for v, w in adj[u]:
            tentative_dist = dist[u] + w
            if tentative_dist < dist[v]:
                dist[v] = tentative_dist
                heappush(heap, (tentative_dist + heuristic(v), v))
    return -1

def bfs_unweighted(n, adj, s, t):
    visited = [False] * n
    queue = [s]
    visited[s] = True
    distance = [float('inf')] * n
    distance[s] = 0

    while queue:
        u = queue.pop(0)
        if u == t:
            return distance[u]
        for v, _ in adj[u]:
            if not visited[v]:
                visited[v] = True
                distance[v] = distance[u] + 1
                queue.append(v)
    return -1

def bfs_unweighted_queue(n, adj, s, t):
    from collections import deque
    visited = [False] * n
    queue = deque([s])
    visited[s] = True
    distance = [float('inf')] * n
    distance[s] = 0

    while queue:
        u = queue.popleft()
        if u == t:
            return distance[u]
        for v, _ in adj[u]:
            if not visited[v]:
                visited[v] = True
                distance[v] = distance[u] + 1
                queue.append(v)
    return -1
