def solve(grid, start, goal):
    if not grid or not grid[0]:
        return []
    rows, cols = len(grid), len(grid[0])
    start_row, start_col = start
    goal_row, goal_col = goal

    if start_row < 0 or start_row >= rows or start_col < 0 or start_col >= cols:
        return []
    if goal_row < 0 or goal_row >= rows or goal_col < 0 or goal_col >= cols:
        return []
    if grid[start_row][start_col] == '#' or grid[goal_row][goal_col] == '#':
        return []

    if start == goal:
        return [start]

    visited = [[False for _ in range(cols)] for _ in range(rows)]
    path = {}

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '#' or visited[r][c]:
            return False
        visited[r][c] = True
        path[(r, c)] = (start_row, start_col)
        if (r, c) == (goal_row, goal_col):
            return True
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if dfs(nr, nc):
                return True
        return False

    if dfs(start_row, start_col):
        # Reconstruct the path
        current = goal
        result = [current]
        while current != start:
            current = path[current]
            result.append(current)
        return result[::-1]
    else:
        return []
