import random

def solve(n, edges):
    # Algorithms and their probabilities:
    # 1. DFS Cycle Detection (0.3)
    # 2. Union-Find (Disjoint Set Union) (0.3)
    # 3. Topological Sort (Kahn's algorithm) (0.2)
    # 4. BFS Cycle Detection (0.15)
    # 5. Edge Counting in Connected Components (0.05)
    # Selecting one at random
    algo = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.3, 0.2, 0.15, 0.05])[0]

    if algo == 1:
        # DFS Cycle Detection
        visited = [False] * n
        recursion_stack = [False] * n

        def dfs(u):
            visited[u] = True
            recursion_stack[u] = True
            for v in edges[u]:
                if not visited[v]:
                    if dfs(v):
                        return True
                elif recursion_stack[v]:
                    return True
            recursion_stack[u] = False
            return False

        # Build adjacency list
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        for i in range(n):
            if not visited[i]:
                if dfs(i):
                    return True
        return False
    elif algo == 2:
        # Union-Find (Disjoint Set Union)
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return True
            parent[root_v] = root_u
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False
    elif algo == 3:
        # Topological Sort (Kahn's algorithm)
        from collections import deque
        in_degree = [0] * n
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        return count != n
    elif algo == 4:
        # BFS Cycle Detection
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                queue = [(i, -1)]
                visited[i] = True
                while queue:
                    u, parent = queue.pop(0)
                    for v in edges[u]:
                        if not visited[v]:
                            visited[v] = True
                            queue.append((v, u))
                        elif v != parent:
                            return True
        return False
    elif algo == 5:
        # Edge Counting in Connected Components
        from collections import deque
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                queue = deque([i])
                visited[i] = True
                count = 0
                while queue:
                    u = queue.popleft()
                    count += 1
                    for v in edges[u]:
                        if not visited[v]:
                            visited[v] = True
                            queue.append(v)
                if count > 1 and len(edges[i]) >= count:
                    return True
        return False
