import random

def solve(n, edges):
    # Algorithms and their selection probabilities
    # 1. DFS-based cycle detection (probability: 0.4)
    # 2. Union-Find (Disjoint Set Union) (probability: 0.3)
    # 3. BFS-based cycle detection (probability: 0.15)
    # 4. Topological sort (probability: 0.1)
    # 5. Checking for multiple edges and self-loops (probability: 0.05)

    # Choose an algorithm based on the probabilities
    algo = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.3, 0.15, 0.1, 0.05])[0]

    if algo == 1:
        # DFS-based cycle detection
        visited = [False] * n
        recursion_stack = [False] * n

        def has_cycle_dfs(u):
            visited[u] = True
            recursion_stack[u] = True
            for v in adj[u]:
                if not visited[v]:
                    if has_cycle_dfs(v):
                        return True
                elif recursion_stack[v]:
                    return True
            recursion_stack[u] = False
            return False

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        for i in range(n):
            if not visited[i]:
                if has_cycle_dfs(i):
                    return True
        return False

    elif algo == 2:
        # Union-Find (Disjoint Set Union) to detect cycles
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return True
            parent[root_v] = root_u
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False

    elif algo == 3:
        # BFS-based cycle detection
        from collections import deque

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        for start in range(n):
            if not visited[start]:
                queue = deque([(start, -1)])
                visited[start] = True
                while queue:
                    u, parent = queue.popleft()
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            queue.append((v, u))
                        elif v != parent:
                            return True
        return False

    elif algo == 4:
        # Topological sort (only works for directed graphs, but we convert to directed)
        # Since the problem is about undirected graphs, this is not the best approach
        # But included for completeness
        from collections import deque

        adj = [[] for _ in range(n)]
        in_degree = [0] * n

        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
            in_degree[u] += 1
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count != n

    elif algo == 5:
        # Check for multiple edges or self-loops (not sufficient for detecting cycles)
        # But included for completeness
        edge_set = set()
        for u, v in edges:
            if u == v:
                return True
            if (u, v) in edge_set or (v, u) in edge_set:
                return True
            edge_set.add((u, v))
        return False
