    elif selected_algo == "Topological Sort":
        from collections import defaultdict, deque

        graph = defaultdict(list)
        in_degree = [0] * n

        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count != n

    elif selected_algo == "BFS-based Cycle Detection":
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n

        def has_cycle():
            queue = deque()
            for i in range(n):
                if not visited[i]:
                    visited[i] = True
                    queue.append((i, -1))
                    while queue:
                        u, parent = queue.popleft()
                        for v in adj[u]:
                            if not visited[v]:
                                visited[v] = True
                                queue.append((v, u))
                            elif v != parent:
                                return True
