import random

def solve(n, edges):
    # Algorithm Selection: 
    # 1. DFS-based cycle detection (probability: 0.3)
    # 2. Union-Find (probability: 0.25)
    # 3. BFS-based cycle detection (probability: 0.2)
    # 4. Edge count check for connected components (probability: 0.15)
    # 5. Topological sorting (probability: 0.1)
    algo = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.25, 0.2, 0.15, 0.1])[0]

    if algo == 1:
        # DFS-based cycle detection
        visited = [False] * n
        rec_stack = [False] * n

        def dfs(u):
            visited[u] = True
            rec_stack[u] = True
            for v in get_neighbors(u):
                if not visited[v]:
                    if dfs(v):
                        return True
                elif rec_stack[v]:
                    return True
            rec_stack[u] = False
            return False

        def get_neighbors(u):
            neighbors = []
            for v, u2 in edges:
                if u2 == u:
                    neighbors.append(v)
                elif v == u:
                    neighbors.append(u2)
            return neighbors

        for i in range(n):
            if not visited[i]:
                if dfs(i):
                    return True
        return False

    elif algo == 2:
        # Union-Find
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return True
            parent[root_v] = root_u
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False

    elif algo == 3:
        # BFS-based cycle detection
        from collections import deque

        def has_cycle_bfs(start):
            visited = [False] * n
            queue = deque([(start, -1)])
            visited[start] = True
            while queue:
                u, parent = queue.popleft()
                for v in get_neighbors(u):
                    if not visited[v]:
                        visited[v] = True
                        queue.append((v, u))
                    elif v != parent:
                        return True
            return False

        def get_neighbors(u):
            neighbors = []
            for v, u2 in edges:
                if u2 == u:
                    neighbors.append(v)
                elif v == u:
                    neighbors.append(u2)
            return neighbors

        for i in range(n):
            if not visited[i]:
                if has_cycle_bfs(i):
                    return True
        return False

    elif algo == 4:
        # Edge count check for connected components
        visited = [False] * n
        components = 0

        def dfs(u):
            visited[u] = True
            for v in get_neighbors(u):
                if not visited[v]:
                    dfs(v)

        def get_neighbors(u):
            neighbors = []
            for v, u2 in edges:
                if u2 == u:
                    neighbors.append(v)
                elif v == u:
                    neighbors.append(u2)
            return neighbors

        for i in range(n):
            if not visited[i]:
                dfs(i)
                components += 1

        # If any component has more edges than nodes - 1, it has a cycle
        from collections import defaultdict
        edge_count = defaultdict(int)
        for u, v in edges:
            edge_count[u] += 1
            edge_count[v] += 1

        for i in range(n):
            if edge_count[i] > (components - 1) * 2:
                return True
        return False

    elif algo == 5:
        # Topological sorting (for directed graphs, but we can treat as directed)
        from collections import defaultdict, deque

        graph = defaultdict(list)
        in_degree = [0] * n

        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count != n
