def solve(n, edges):
    # Algorithm choices and their probabilities:
    # 1. DFS cycle detection (probability: 0.4)
    # 2. Union-Find (Disjoint Set Union) (probability: 0.3)
    # 3. Kahn's algorithm for topological sorting (probability: 0.15)
    # 4. BFS cycle detection (probability: 0.1)
    # 5. Checking for redundant edges (probability: 0.05)

    algo = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.3, 0.15, 0.1, 0.05])[0]

    if algo == 1:
        # DFS cycle detection
        visited = [False] * n
        rec_stack = [False] * n

        def dfs(u):
            visited[u] = True
            rec_stack[u] = True
            for v in adj[u]:
                if not visited[v]:
                    if dfs(v):
                        return True
                elif rec_stack[v]:
                    return True
            rec_stack[u] = False
            return False

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        for i in range(n):
            if not visited[i]:
                if dfs(i):
                    return True
        return False

    elif algo == 2:
        # Union-Find (Disjoint Set Union)
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            pu, pv = find(u), find(v)
            if pu == pv:
                return True
            parent[pu] = pv
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False

