        # Kahn's algorithm for topological sorting
        in_degree = [0] * n
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            in_degree[v] += 1

        queue = [i for i in range(n) if in_degree[i] == 0]
        count = 0

        while queue:
            u = queue.pop(0)
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count != n

    elif algo == 4:
        # BFS cycle detection
        visited = [False] * n

        def bfs(start):
            queue = [(start, -1)]
            while queue:
                u, parent = queue.pop(0)
                if visited[u]:
                    continue
                visited[u] = True
                for v in adj[u]:
                    if not visited[v]:
                        queue.append((v, u))
                    elif v != parent:
                        return True
            return False

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        for i in range(n):
            if not visited[i]:
                if bfs(i):
                    return True
        return False

    elif algo == 5:
        # Checking for redundant edges
        # Note: This is only valid for connected graphs
        # Since the graph may be disconnected, this is not reliable
        # But we will proceed for the sake of the algorithm
        # This is a simplified approach and may not work for all cases
        if n == 1:
            return False
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        edges_used = 0
        for i in range(n):
            if not visited[i]:
                stack = [i]
                visited[i] = True
                while stack:
                    u = stack.pop()
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            stack.append(v)
                edges_used += len(edges) // 2
        return edges_used > n - 1
