import random

def solve(n, edges):
    # Algorithms and their probabilities:
    # 1. DFS Cycle Detection (probability 0.4)
    # 2. Union-Find (Disjoint Set Union) (probability 0.3)
    # 3. BFS Cycle Detection (probability 0.15)
    # 4. Topological Sort (probability 0.1)
    # 5. Hash-based Edge Counting (probability 0.05)

    algo = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.3, 0.15, 0.1, 0.05])[0]

    if algo == 1:
        # DFS-based cycle detection
        visited = [False] * n
        recursion_stack = [False] * n

        def dfs(u):
            visited[u] = True
            recursion_stack[u] = True
            for v in range(n):
                if edges[u][v]:
                    if not visited[v]:
                        if dfs(v):
                            return True
                    elif recursion_stack[v]:
                        return True
            recursion_stack[u] = False
            return False

        for i in range(n):
            if not visited[i]:
                if dfs(i):
                    return True
        return False

    elif algo == 2:
        # Union-Find (Disjoint Set Union) for cycle detection
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x == root_y:
                return True
            parent[root_y] = root_x
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False

    elif algo == 3:
        # BFS-based cycle detection
        from collections import deque

        visited = [False] * n
        for start in range(n):
            if not visited[start]:
                queue = deque()
                queue.append((start, -1))  # (current node, parent)
                visited[start] = True
                while queue:
                    u, parent = queue.popleft()
                    for v in range(n):
                        if edges[u][v]:
                            if not visited[v]:
                                visited[v] = True
                                queue.append((v, u))
                            elif v != parent:
                                return True
        return False

    elif algo == 4:
        # Topological sort (only for DAGs)
        from collections import defaultdict, deque

        graph = defaultdict(list)
        in_degree = [0] * n

        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            node = queue.popleft()
            count += 1
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return count != n

    elif algo == 5:
        # Hash-based edge counting (for simple cycle check in complete graph)
        # This is not reliable for general graphs, but used for the sake of the exercise
        edge_set = set()
        for u, v in edges:
            if u > v:
                u, v = v, u
            edge_set.add((u, v))

        for u in range(n):
            for v in range(n):
                if u < v and (u, v) in edge_set:
                    for w in range(n):
                        if w != u and w != v and (u, w) in edge_set and (w, v) in edge_set:
                            return True
        return False
