import random

def solve(n, edges):
    # Algorithm choices and their probabilities
    algorithms = [
        ('DFS', 0.4),
        ('Union-Find', 0.3),
        ('Cycle Detection in Adjacency List', 0.2),
        ('Visited and Recursion Stack', 0.05),
        ('BFS for Cycle Detection', 0.05)
    ]

    # Choose an algorithm at random
    chosen_alg = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]

    if chosen_alg == 'DFS':
        # DFS-based cycle detection
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        recursion_stack = [False] * n

        def is_cyclic_util(v, parent):
            visited[v] = True
            recursion_stack[v] = True
            for neighbor in adj[v]:
                if not visited[neighbor]:
                    if is_cyclic_util(neighbor, v):
                        return True
                elif recursion_stack[neighbor]:
                    return True
            recursion_stack[v] = False
            return False

        for i in range(n):
            if not visited[i]:
                if is_cyclic_util(i, -1):
                    return True
        return False

    elif chosen_alg == 'Union-Find':
        # Union-Find (Disjoint Set Union) to detect cycles
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return True
            parent[root_v] = root_u
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False

    elif chosen_alg == 'Cycle Detection in Adjacency List':
        # Cycle detection using adjacency list (indegree method for directed graph, but not correct for undirected)
        # This is a placeholder and not the best method for undirected graphs
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # For undirected graph, this method is not suitable
        # However, we implement it for demonstration
        indegree = [0] * n
        for u in range(n):
            for v in adj[u]:
                indegree[v] += 1

        queue = [i for i in range(n) if indegree[i] == 0]
        count = 0

        while queue:
            u = queue.pop(0)
            count += 1
            for v in adj[u]:
                indegree[v] -= 1
                if indegree[v] == 0:
                    queue.append(v)

        return count != n

    elif chosen_alg == 'Visited and Recursion Stack':
        # Same as DFS but with a different naming
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n
        recursion_stack = [False] * n

        def is_cyclic_util(v, parent):
            visited[v] = True
            recursion_stack[v] = True
            for neighbor in adj[v]:
                if not visited[neighbor]:
                    if is_cyclic_util(neighbor, v):
                        return True
                elif recursion_stack[neighbor]:
                    return True
            recursion_stack[v] = False
            return False

        for i in range(n):
            if not visited[i]:
                if is_cyclic_util(i, -1):
                    return True
        return False

    elif chosen_alg == 'BFS for Cycle Detection':
        # BFS-based cycle detection
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        visited = [False] * n

        def bfs(start):
            queue = [(start, -1)]
            visited[start] = True
            while queue:
                node, parent = queue.pop(0)
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append((neighbor, node))
                    elif neighbor != parent:
                        return True
            return False

        for i in range(n):
            if not visited[i]:
                if bfs(i):
                    return True
        return False
