import random

def solve(n, edges):
    # Algorithm selection probabilities
    # 1. DFS cycle detection (probability: 0.4)
    # 2. Union-Find (probability: 0.3)
    # 3. BFS cycle detection (probability: 0.2)
    # 4. Tarjan's algorithm (probability: 0.05)
    # 5. Kahn's algorithm for cycle detection (probability: 0.05)
    algo = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.3, 0.2, 0.05, 0.05])[0]

    if algo == 1:
        # DFS cycle detection
        visited = [False] * n
        recursion_stack = [False] * n

        def dfs(u):
            visited[u] = True
            recursion_stack[u] = True
            for v in range(n):
                if edges[u][v]:
                    if not visited[v]:
                        if dfs(v):
                            return True
                    elif recursion_stack[v]:
                        return True
            recursion_stack[u] = False
            return False

        for u in range(n):
            if not visited[u]:
                if dfs(u):
                    return True
        return False

    elif algo == 2:
        # Union-Find
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return False
            parent[root_v] = root_u
            return True

        for u, v in edges:
            if not union(u, v):
                return True
        return False

    elif algo == 3:
        # BFS cycle detection
        from collections import deque

        visited = [False] * n
        for start in range(n):
            if not visited[start]:
                queue = deque()
                queue.append((start, -1))
                visited[start] = True
                while queue:
                    node, prev = queue.popleft()
                    for neighbor in range(n):
                        if edges[node][neighbor]:
                            if neighbor == prev:
                                continue
                            if visited[neighbor]:
                                return True
                            visited[neighbor] = True
                            queue.append((neighbor, node))
        return False

    elif algo == 4:
        # Tarjan's algorithm for cycle detection
        visited = [False] * n
        recursion_stack = [False] * n
        stack = []

        def tarjan(v):
            visited[v] = True
            recursion_stack[v] = True
            stack.append(v)
            for u in range(n):
                if edges[v][u]:
                    if not visited[u]:
                        if tarjan(u):
                            return True
                    elif recursion_stack[u]:
                        return True
            recursion_stack[v] = False
            stack.pop()
            return False

        for v in range(n):
            if not visited[v]:
                if tarjan(v):
                    return True
        return False

    elif algo == 5:
        # Kahn's algorithm for cycle detection
        from collections import deque

        in_degree = [0] * n
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count != n
