                        if edges[node][neighbor]:
                            if not visited[neighbor]:
                                visited[neighbor] = True
                                queue.append((neighbor, node))
                            elif prev != neighbor:
                                return True
        return False

    elif selected == 'topo':
        from collections import defaultdict, deque

        graph = defaultdict(list)
        in_degree = [0] * n

        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return count != n

    elif selected == 'edge_count':
        visited = [False] * n
        for start in range(n):
            if not visited[start]:
                stack = [start]
                visited[start] = True
                count = 1
                while stack:
                    node = stack.pop()
                    for neighbor in range(n):
                        if edges[node][neighbor]:
                            if not visited[neighbor]:
                                visited[neighbor] = True
                                count += 1
                                stack.append(neighbor)
                if count > 1:
                    return True
        return False
