        count = 0
        while queue:
            u = queue.popleft()
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        return count != n
    elif chosen == "Tarjan's Strongly Connected Components":
        index = 0
        indices = [-1] * n
        lowlink = [-1] * n
        on_stack = [False] * n
        stack = []
        def strongconnect(v):
            nonlocal index
            indices[v] = index
            lowlink[v] = index
            index += 1
            stack.append(v)
            on_stack[v] = True
            for w in adj[v]:
                if indices[w] == -1:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif on_stack[w]:
                    lowlink[v] = min(lowlink[v], indices[w])
            if lowlink[v] == indices[v]:
                while True:
                    w = stack.pop()
                    on_stack[w] = False
                    if w == v:
                        break
        for v in range(n):
            if indices[v] == -1:
                strongconnect(v)
        return any(lowlink[v] == indices[v] for v in range(n))
    return False
