    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Precompute the prefix function for the needle
    prefix = [0] * len_n
    for i in range(1, len_n):
        j = prefix[i - 1]
        while j > 0 and needle[i] != needle[j]:
            j = prefix[j - 1]
        if needle[i] == needle[j]:
            j += 1
        prefix[i] = j

    # Knuth-Morris-Pratt search
    j = 0
    for i in range(len_h):
        while j > 0 and haystack[i] != needle[j]:
            j = prefix[j - 1]
        if haystack[i] == needle[j]:
            j += 1
        if j == len_n:
            return i - len_n + 1
    return -1
