def solve(haystack, needle):
    if len(needle) > len(haystack):
        return -1

    def rolling_hash(s, base=257, mod=10**9 + 7):
        hash_val = 0
        for char in s:
            hash_val = (hash_val * base + ord(char)) % mod
        return hash_val

    def get_prefix_function(pattern):
        pi = [0] * len(pattern)
        for i in range(1, len(pattern)):
            j = pi[i - 1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j
        return pi

    def kmp_search(text, pattern):
        pi = get_prefix_function(pattern)
        j = 0
        for i in range(len(text)):
            while j > 0 and text[i] != pattern[j]:
                j = pi[j - 1]
            if text[i] == pattern[j]:
                j += 1
            if j == len(pattern):
                return i - len(pattern) + 1
        return -1

    def rabin_karp_search(text, pattern):
        base = 257
        mod = 10**9 + 7
        n = len(text)
        m = len(pattern)
        if m > n:
            return -1
        hash_pattern = rolling_hash(pattern, base, mod)
        hash_text = rolling_hash(text[:m], base, mod)
        power = pow(base, m - 1, mod)

        for i in range(n - m + 1):
            if hash_text == hash_pattern:
                if text[i:i + m] == pattern:
                    return i
            if i < n - m:
                hash_text = (hash_text - ord(text[i]) * power) % mod
                hash_text = (hash_text * base + ord(text[i + m])) % mod
        return -1

    return kmp_search(haystack, needle)
