def solve():
    def get_prefix_function(pattern):
        m = len(pattern)
        pi = [0] * m
        for i in range(1, m):
            j = pi[i-1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j-1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j
        return pi

    def kmp_search(text, pattern):
        n = len(text)
        m = len(pattern)
        if m == 0 or m > n:
            return -1
        pi = get_prefix_function(pattern)
        j = 0
        for i in range(n):
            while j > 0 and text[i] != pattern[j]:
                j = pi[j-1]
            if text[i] == pattern[j]:
                j += 1
            if j == m:
                return i - m + 1
        return -1

    n = int(input())
    for _ in range(n):
        s = input().strip()
        t = input().strip()
        print(kmp_search(s, t))
