def solve():
    import sys
    import re

    def find_substring():
        try:
            input_lines = sys.stdin.read().splitlines()
            if not input_lines:
                return -1
            text = input_lines[0]
            pattern = input_lines[1] if len(input_lines) > 1 else ''
            if len(pattern) > len(text):
                return -1
            if not pattern:
                return 0
            match = re.search(re.escape(pattern), text)
            return match.start() if match else -1
        except:
            return -1

    print(find_substring())
