def solve(haystack, needle):
    len_h = len(haystack)
    len_n = len(needle)

    if len_n > len_h:
        return -1

    # Preprocess the needle to create a list of character positions
    last_pos = {}
    for i, char in enumerate(needle):
        last_pos[char] = i

    # Initialize variables for the current position and the shift
    current = 0
    shift = 0

    while current <= len_h - len_n:
        # Check if the current substring matches the needle
        match = True
        for i in range(len_n):
            if haystack[current + i] != needle[i]:
                match = False
                break
        if match:
            return current

        # Find the last occurrence of the character that failed the match
        # and shift accordingly
        if current + len_n < len_h:
            char = haystack[current + len_n]
            if char in last_pos:
                shift = last_pos[char] + 1
            else:
                shift = len_n
        else:
            shift = len_n

        current += shift

    return -1
```

