def solve(haystack, needle):
    def kmp_failure(pattern):
        m = len(pattern)
        fail = [0] * m
        j = 0
        for i in range(1, m):
            while j > 0 and pattern[i] != pattern[j]:
                j = fail[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                fail[i] = j
            else:
                fail[i] = 0
        return fail

    def kmp_search(text, pattern, fail):
        n = len(text)
        m = len(pattern)
        j = 0
        for i in range(n):
            while j > 0 and text[i] != pattern[j]:
                j = fail[j - 1]
            if text[i] == pattern[j]:
                j += 1
            if j == m:
                return i - m + 1
        return -1

    if len(needle) > len(haystack):
        return -1
    fail = kmp_failure(needle)
    return kmp_search(haystack, needle, fail)
```

