def solve(intervals):
    if not intervals:
        return 0

    intervals.sort()
    n = len(intervals)
    dp = [1] * n
    prev = [0] * n

    for i in range(n):
        for j in range(i):
            if intervals[j][1] <= intervals[i][0]:
                if dp[j] + 1 > dp[i]:
                    dp[i] = dp[j] + 1
                    prev[i] = j

    max_len = max(dp)
    result = [0] * max_len
    idx = max_len - 1

    for i in range(n - 1, -1, -1):
        if dp[i] == max_len:
            result[idx] = intervals[i][0]
            idx -= 1
            if prev[i] != 0:
                result[idx] = intervals[i][1]
                idx -= 1

    return max_len
```

