def solve(intervals):
    def is_valid(point, interval):
        start, end = interval
        return start <= point <= end

    def dfs(point, index, visited):
        if index == len(intervals):
            return 1
        max_count = 0
        for i in range(index, len(intervals)):
            if not visited[i] and is_valid(point, intervals[i]):
                visited[i] = True
                max_count = max(max_count, 1 + dfs(point, i + 1, visited))
                visited[i] = False
        return max_count

    visited = [False] * len(intervals)
    return dfs(0, 0, visited)
```

