def solve(n):
    def fib_matrix_power(n):
        def multiply(a, b):
            return [
                [a[0]*b[0] + a[1]*b[2], a[0]*b[1] + a[1]*b[3]],
                [a[2]*b[0] + a[3]*b[2], a[2]*b[1] + a[3]*b[3]]
            ]

        def matrix_power(mat, power):
            result = [[1, 0], [0, 1]]  # Identity matrix
            while power > 0:
                if power % 2 == 1:
                    result = multiply(result, mat)
                mat = multiply(mat, mat)
                power //= 2
            return result

        if n == 0:
            return 0
        elif n == 1:
            return 1

        matrix = [[1, 1], [1, 0]]
        powered = matrix_power(matrix, n - 1)
        return powered[0][0]

    return fib_matrix_power(n)
