def solve(n):
    def multiply(a, b):
        p = len(a)
        q = len(b)
        result = [0] * (p + q)
        for i in range(p):
            for j in range(q):
                result[i + j] += a[i] * b[j]
        return result

    def power(matrix, power):
        result = [1] + [0] * len(matrix)
        while power > 0:
            if power % 2 == 1:
                result = multiply(result, matrix)
            matrix = multiply(matrix, matrix)
            power //= 2
        return result

    def fibonacci(n):
        if n == 0:
            return 0
        if n == 1:
            return 1
        matrix = [1, 1, 1, 0]
        result = power(matrix, n - 1)
        return result[0]

    return fibonacci(n)
