        return 0
    elif n == 1:
        return 1

    def fib_matrix(n):
        if n == 1:
            return [[1, 1], [1, 0]]
        else:
            return matrix_mult(fib_matrix(n // 2), fib_matrix(n - n // 2))

    mat = fib_matrix(n)
    return mat[0][1]
