def solve():
    import sys
    sys.setrecursionlimit(10000)

    def get_input():
        n = int(input())
        return n

    def get_edges(n):
        edges = []
        for _ in range(n - 1):
            a, b = map(int, input().split())
            edges.append((a, b))
        return edges

    def build_graph(n, edges):
        graph = {i: [] for i in range(n)}
        in_degree = [0] * n
        for a, b in edges:
            graph[b].append(a)
            in_degree[a] += 1
        return graph, in_degree

    def topological_sort(graph, in_degree):
        queue = [i for i in range(len(in_degree)) if in_degree[i] == 0]
        result = []
        while queue:
            node = queue.pop(0)
            result.append(node)
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)
        if len(result) != len(in_degree):
            return []  # Cycle detected
        return result

    n = get_input()
    edges = get_edges(n)
    graph, in_degree = build_graph(n, edges)
    result = topological_sort(graph, in_degree)
    if not result:
        print([])
    else:
        print(result)
