def solve():
    from collections import defaultdict, deque

    def dfs(node, graph, visited, order, has_cycle):
        if has_cycle[0]:
            return
        visited[node] = True
        for neighbor in graph[node]:
            if visited[neighbor]:
                has_cycle[0] = True
                return
            dfs(neighbor, graph, visited, order, has_cycle)
        order.append(node)

    def solve_helper(graph, n):
        visited = [False] * n
        order = []
        has_cycle = [False]
        for node in range(n):
            if not visited[node]:
                dfs(node, graph, visited, order, has_cycle)
                if has_cycle[0]:
                    return []
        return order[::-1]

    def build_graph(adj, n):
        graph = defaultdict(list)
        for a, b in adj:
            graph[a].append(b)
        return graph

    def solve_main(adj, n):
        if not adj:
            return list(range(n))
        graph = build_graph(adj, n)
        return solve_helper(graph, n)

    return solve_main
