def solve():
    from collections import deque

    def topological_sort(n, edges):
        graph = [[] for _ in range(n)]
        in_degree = [0] * n

        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1

        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        result = []
        while queue:
            u = queue.popleft()
            result.append(u)
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return result if len(result) == n else []

    def helper(tasks, edges):
        if not tasks:
            return []
        n = len(tasks)
        edges = [(u, v) for u in range(n) for v in range(n) if u != v and edges[u][v]]
        return topological_sort(n, edges)

    return helper
