def solve(intervals):
    def merge(intervals):
        if not intervals:
            return []
        intervals.sort()
        merged = [intervals[0]]
        for current in intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1][1] = max(last[1], current[1])
            else:
                merged.append(current)
        return merged

    def find_conflicts(intervals):
        n = len(intervals)
        conflicts = [0] * n
        for i in range(n):
            for j in range(i + 1, n):
                if intervals[i][1] >= intervals[j][0]:
                    conflicts[i] += 1
                    conflicts[j] += 1
        return conflicts

    def get_conflict_free(intervals):
        n = len(intervals)
        conflict_free = [True] * n
        for i in range(n):
            for j in range(i + 1, n):
                if intervals[i][1] >= intervals[j][0]:
                    conflict_free[i] = False
                    conflict_free[j] = False
        return conflict_free

    def get_intervals_with_conflicts(intervals):
        n = len(intervals)
        conflict_free = get_conflict_free(intervals)
        result = []
        for i in range(n):
            if conflict_free[i]:
                result.append(intervals[i])
        return result

    def get_conflict_intervals(intervals):
        n = len(intervals)
        conflicts = find_conflicts(intervals)
        conflict_intervals = []
        for i in range(n):
            if conflicts[i] > 0:
                conflict_intervals.append(intervals[i])
        return conflict_intervals

    def get_merged_intervals(conflict_intervals):
        if not conflict_intervals:
            return []
        conflict_intervals.sort()
        merged = [conflict_intervals[0]]
        for current in conflict_intervals[1:]:
            last = merged[-1]
            if current[0] <= last[1]:
                merged[-1][1] = max(last[1], current[1])
            else:
                merged.append(current)
        return merged

    def get_final_intervals(intervals, merged_conflicts):
        conflict_free = get_intervals_with_conflicts(intervals)
        merged_conflicts = get_merged_intervals(get_conflict_intervals(intervals))
        result = conflict_free + merged_conflicts
        result.sort()
        return result

    return get_final_intervals(intervals, [])
