def solve(nums):
    from collections import Counter

    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def get_primes_upto(n):
        sieve = [True] * (n + 1)
        sieve[0] = sieve[1] = False
        for i in range(2, int(n**0.5) + 1):
            if sieve[i]:
                for j in range(i*i, n+1, i):
                    sieve[j] = False
        return [i for i, is_p in enumerate(sieve) if is_p]

    def get_prime_factors(n):
        factors = []
        if n < 2:
            return factors
        while n % 2 == 0:
            factors.append(2)
            n //= 2
        i = 3
        while i * i <= n:
            while n % i == 0:
                factors.append(i)
                n //= i
            i += 2
        if n > 1:
            factors.append(n)
        return factors

    def is_valid(n):
        return all(is_prime(p) for p in get_prime_factors(n))

    def get_kth_value(n, k):
        primes = get_primes_upto(n)
        return primes[k - 1] if k - 1 < len(primes) else None

    def encode(n):
        if is_valid(n):
            return get_kth_value(n, len(get_prime_factors(n)))
        return n

    encoded = [encode(x) for x in nums]
    counter = Counter(encoded)
    return [num for num, _ in counter.most_common() if num in counter]
