    def find_median(nums):
        sorted_nums = sorted(nums)
        n = len(sorted_nums)
        return sorted_nums[n // 2]

    def find_mode(nums):
        from collections import Counter
        counts = Counter(nums)
        return max(counts, key=counts.get)

    def find_range(nums):
        return max(nums) - min(nums)

    def find_sum(nums):
        return sum(nums)

    def find_avg(nums):
        return sum(nums) / len(nums)

    def find_unique(nums):
        return len(set(nums))

    def find_duplicate(nums):
        seen = set()
        for num in nums:
            if num in seen:
                return num
            seen.add(num)
        return None

    return {
        'kth_largest': find_kth_largest,
        'kth_smallest': find_kth_smallest,
        'max': find_max_min,
        'min': find_max_min,
        'median': find_median,
        'mode': find_mode,
        'range': find_range,
        'sum': find_sum,
        'avg': find_avg,
        'unique': find_unique,
        'duplicate': find_duplicate
    }
