def solve(nums, k):
    count = defaultdict(int)
    for num in nums:
        count[num] += 1

    freq = list(count.items())
    freq.sort(key=lambda x: (-x[1], x[0]))

    result = []
    current_freq = freq[0][1]
    count_val = 1

    for i in range(1, len(freq)):
        if freq[i][1] < current_freq:
            while count_val < k:
                result.append(freq[i - 1][0])
                count_val += 1
            break
        elif freq[i][1] == current_freq:
            count_val += 1
        else:
            break

    if count_val < k:
        result.append(freq[-1][0])

    return result
