def solve(nums):
    def helper(nums, index, memo):
        if index in memo:
            return memo[index]
        if index >= len(nums):
            return 0
        max_len = 1
        for i in range(index + 1, len(nums)):
            if nums[i] > nums[index]:
                current = 1 + helper(nums, i, memo)
                max_len = max(max_len, current)
        memo[index] = max_len
        return max_len

    memo = {}
    result = helper(nums, 0, memo)
    return result
