    def insert(sorted_list, value):
        index = bisect_left(sorted_list, value)
        if index == len(sorted_list):
            sorted_list.append(value)
        else:
            sorted_list[index] = value

    dp = []
    for num in nums:
        insert(dp, num)
    return len(dp)
