def solve(nums):
    def count_subsequences(i, j, prev):
        if i >= len(nums):
            return 1
        if nums[i] < prev:
            return count_subsequences(i + 1, j, prev)
        elif nums[i] == prev:
            return count_subsequences(i + 1, j, prev)
        else:
            return count_subsequences(i + 1, j, nums[i]) + count_subsequences(i + 1, j, prev)

    return count_subsequences(0, 0, -float('inf'))
```

