def solve(nums):
    def count_lis(start, dp):
        if start >= len(nums):
            return 0
        if dp[start] != -1:
            return dp[start]
        max_len = 1
        for i in range(start + 1, len(nums)):
            if nums[i] > nums[start]:
                current = 1 + count_lis(i, dp)
                max_len = max(max_len, current)
        dp[start] = max_len
        return max_len

    dp = [-1] * len(nums)
    max_length = 0
    for i in range(len(nums) - 1, -1, -1):
        max_length = max(max_length, count_lis(i, dp))
    return max_length
```

