def solve(nums):
    def count_increasing():
        n = len(nums)
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if nums[j] < nums[i]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return dp

    def count_decreasing():
        n = len(nums)
        dp = [1] * n
        for i in range(n):
            for j in range(i):
                if nums[j] > nums[i]:
                    dp[i] = max(dp[i], dp[j] + 1)
        return dp

    inc = count_increasing()
    dec = count_decreasing()
    return max(inc[i] + dec[i] - 1 for i in range(len(nums)))
```

