def solve(nums):
    def update_sequence(seq, num):
        left, right = 0, len(seq)
        while left < right:
            mid = (left + right) // 2
            if seq[mid] < num:
                left = mid + 1
            else:
                right = mid
        if left == len(seq):
            seq.append(num)
        else:
            seq[left] = num
        return seq

    if not nums:
        return 0
    seq = []
    for num in nums:
        seq = update_sequence(seq, num)
    return len(seq)
