def solve(nums):
    def count_positive():
        return sum(1 for x in nums if x > 0)

    def count_negative():
        return sum(1 for x in nums if x < 0)

    def count_zero():
        return sum(1 for x in nums if x == 0)

    positive = count_positive()
    negative = count_negative()
    zero = count_zero()

    return positive + negative + zero
```

