def solve(nums):
    def count_sequences(i, prev):
        if i == len(nums):
            return 0
        take = 0
        if nums[i] > prev:
            take = 1 + count_sequences(i + 1, nums[i])
        skip = count_sequences(i + 1, prev)
        return max(take, skip)

    return count_sequences(0, float('-inf'))
```

