        if i == len(nums):
            return 1
        if nums[i] <= current_max:
            return count_increasing_sequences(i + 1, current_max)
        return max(count_increasing_sequences(i + 1, nums[i]), 1 + count_increasing_sequences(i + 1, nums[i]))

    return count_increasing_sequences(0, float('-inf'))
