def solve(nums):
    def count_incr_subseqs(i, prev):
        if i == len(nums):
            return 1
        longest = 1
        if nums[i] > prev:
            longest = max(longest, count_incr_subseqs(i + 1, nums[i]))
        longest = max(longest, count_incr_subseqs(i + 1, prev))
        return longest

    max_len = 1
    for i in range(len(nums)):
        max_len = max(max_len, count_incr_subseqs(i, float('-inf')))
    return max_len
