def solve(nums):
    def longest_increasing_subsequence(start_idx):
        if start_idx >= len(nums):
            return []
        current = [nums[start_idx]]
        for i in range(start_idx + 1, len(nums)):
            if nums[i] > current[-1]:
                current.append(nums[i])
        return current

    max_subseq = []
    for i in range(len(nums)):
        subseq = longest_increasing_subsequence(i)
        if len(subseq) > len(max_subseq):
            max_subseq = subseq
    return len(max_subseq)
```

