def solve(nums):
    if not nums:
        return []

    dp = [1] * len(nums)
    max_length = 1
    index = 0

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[j] < nums[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                if dp[i] > max_length:
                    max_length = dp[i]
                    index = i

    result = []
    for i in range(len(nums)-1, -1, -1):
        if dp[i] == max_length:
            result.append(nums[i])
            max_length -= 1

    return result[::-1]
