def solve(nums):
    def update(dp, i, val):
        for j in range(i, len(dp)):
            if dp[j] < val:
                dp[j] = val
                break
        return dp

    dp = [float('inf')] * len(nums)
    for i, num in enumerate(nums):
        dp[i] = num
        for j in range(i + 1, len(nums)):
            if nums[j] > num:
                dp = update(dp, j, nums[j])
    return max(dp)
